import type {Item} from './content';

// Original Spanish teaching notes. References are further reading, not copied textbook passages.
// Each course has six original topics followed by its extension topics in stable ID order.
type CourseNotes = {context: string; reading: [string,string][]; lessons: [string,string][]};
const general: [string,string][] = [['OpenStax · Química 2ed (español)', 'https://openstax.org/books/qu%C3%ADmica-2ed/pages/1-introduccion']];
const analytical: [string,string][] = [['David Harvey · Analytical Chemistry 2.1 (inglés)', 'https://sites.google.com/depauw.edu/dth/analytical-curriculum-projects/ac2-1']];
const statistics: [string,string][] = [['NIST · Manual de métodos estadísticos (inglés)', 'https://www.itl.nist.gov/div898/handbook/']];
export const courseNotes: Record<string, CourseNotes> = {
 'volatilomica': {context:'La volatilómica estudia perfiles de sustancias transferidas a la fase gaseosa desde sistemas biológicos, alimentos o ambientes. El perfil observado combina producción, partición, transporte, conservación y respuesta instrumental. Una señal no demuestra por sí sola origen biológico, identidad ni utilidad como biomarcador. El análisis de posgrado debe justificar controles ambientales y de materiales, especificar unidades y condiciones y validar resultados en muestras independientes antes de generalizar.',reading:[['NIST · Datos de retención cromatográfica (inglés)','https://webbook.nist.gov/chemistry/gc-ri/'],['ERS · Estándar técnico de biomarcadores exhalados, 2017 (inglés)','https://publications.ersnet.org/content/erj/49/4/1600965'],...analytical],lessons:[
 ['El espacio de cabeza contiene compuestos distribuidos desde la muestra según partición y condiciones. SPME concentra selectivamente sustancias en un recubrimiento sin extraer necesariamente todo el analito. Tiempo, temperatura, agitación y relación de volúmenes afectan respuesta; calibración debe reproducir el procedimiento.','Una fibra con mayor señal de un compuesto no demuestra mayor concentración original si cambia temperatura o tiempo de extracción. Diseña una comparación controlada.'],
 ['Blancos de materiales, transporte y procedimiento permiten localizar contaminación. La estabilidad depende de compuesto, recipiente, humedad y duración. Un único blanco instrumental no evalúa toda la cadena; deben registrarse tiempos y condiciones desde obtención hasta medición.','Una señal aparece en bolsas vacías y muestras. Compara niveles y variabilidad antes de atribuirla al organismo estudiado.'],
 ['GC-MS combina separación temporal e información espectral para mezclas volátiles. Temperatura, inyección y columna pueden discriminar o transformar componentes. La coincidencia espectral requiere evaluar coelución y retención; un pico aislado visualmente aún puede contener más de una especie.','Examina proporciones de iones a lo largo de un pico. Cambios sistemáticos pueden indicar interferencia y justificar otra condición de separación.'],
 ['Los índices de retención relacionan comportamiento con una serie de referencia y una convención definida. Las bibliotecas son evidencia comparativa dependiente de condiciones. El índice isotérmico de Kováts y el lineal bajo programación de temperatura no se calculan exactamente igual.','Compara un candidato con referencias de polaridad de fase similar. Explica por qué un índice de otra fase no es una confirmación directa.'],
 ['Los perfiles volátiles contienen señales correlacionadas y posibles efectos de lote, ambiente o humedad. El preprocesamiento y la validación deben mantener independencia de sujetos y sesiones. Clasificar muestras correctamente en entrenamiento no prueba generalización ni especificidad química.','Una separación por día de muestreo puede dominar PCA. Revisa variables ambientales antes de interpretarla como patrón de enfermedad o tratamiento.'],
 ['Aplicaciones en alimentos, ambiente y biología requieren distintos criterios de validación. Asociación con una condición no demuestra especificidad ni causalidad. Deben estudiarse factores externos, población objetivo y reproducibilidad de muestreo, además de desempeño instrumental.','Un perfil que diferencia dos grupos en un laboratorio necesita evaluación independiente antes de proponerse como herramienta diagnóstica o de control de calidad.'],
 ['La presión de vapor caracteriza equilibrio de una sustancia y depende de temperatura. La partición distribuye analito entre fases según composición y convenciones del coeficiente. Alta volatilidad de la sustancia pura no garantiza alta señal desde una matriz donde existe unión o baja actividad.','Dos matrices con igual concentración total pueden producir espacios de cabeza distintos. Explica el efecto de afinidad por la matriz y temperatura.'],
 ['La emisión combina generación y transporte a través de interfaces. Difusión, espesor de película y flujo pueden controlar velocidad observada. Equilibrio de partición y rapidez de alcanzarlo son conceptos distintos; un muestreo corto puede registrar un estado transitorio.','Cambiar agitación modifica transferencia sin cambiar necesariamente producción química. Diseña un control para distinguir ambos efectos.'],
 ['Los volátiles pueden proceder de metabolismo del huésped, microbiota, dieta, materiales o ambiente. El origen no se deduce solo de detectar un compuesto conocido. Controles, trazadores y diseños temporales ayudan a restringir explicaciones sin atribuir exclusividad injustificada.','Un alcohol aparece en muestra biológica y aire ambiental. Compara antecedentes y blancos antes de asignarlo a una vía metabólica específica.'],
 ['Concentración expresa cantidad por volumen o fracción molar; tasa de emisión expresa cantidad por tiempo. En sistemas con flujo, acumulación y pérdidas conectan ambas mediante balance. Igual concentración no implica igual emisión si cambian caudal, volumen o retención.','En estado estacionario ideal, emisión≈caudal×(concentración de salida−entrada). Señala las pérdidas y acumulaciones omitidas por esa aproximación.'],
 ['Los diseños longitudinales aprovechan comparaciones dentro del sujeto, pero requieren controlar tiempo y entorno. Dieta, medicación, actividad y exposición pueden confundir perfiles. Las visitas correlacionadas no se tratan como sujetos independientes ni se reparten libremente en validación.','Agrupa visitas por individuo al separar datos de entrenamiento y prueba. Explica por qué esto evita reconocer al sujeto en lugar de la condición.'],
 ['Cámaras, bolsas y tubos introducen superficies, volúmenes muertos y posibles emisiones. Compatibilidad depende del compuesto y del tiempo de contacto; adsorción y permeación pueden sesgar perfiles. La selección debe apoyarse en blancos y recuperación, no solo en material nominal.','Compara el mismo estándar en dos recipientes a varios tiempos. Distingue señal liberada por el material y pérdida del analito.'],
 ['La muestra de aliento puede combinar espacio muerto, fracciones de intercambio pulmonar y aportes de vías aéreas. Flujo y modo de recolección afectan composición; medir CO₂ puede ayudar a definir fracciones según protocolo. Esto no convierte una muestra en diagnóstico clínico por sí sola.','Compara recolección de una exhalación completa con una fracción final definida. Explica qué metadatos necesitas para interpretar diferencias sin llamarlas exclusivamente alveolares.'],
 ['Humedad, temperatura y caudal afectan partición, adsorción y respuesta instrumental. La conservación puede modificar agua y compuestos simultáneamente. Controlar una variable no estabiliza todas; es necesario registrar condiciones y comprobar respuesta dentro del intervalo real del estudio.','Una muestra húmeda y un patrón seco pueden responder diferente. Propón calibraciones o controles que evalúen ese desajuste.'],
 ['HS-SPME puede operar cerca del equilibrio o en régimen preequilibrio reproducible. En el segundo, controlar tiempo y transporte es esencial. Extraer más tiempo no siempre aumenta proporcionalmente señal por saturación o competencia entre componentes.','Traza señal frente a tiempo de exposición para varias especies. Explica por qué una meseta común no debe suponerse antes de medir.'],
 ['Recubrimientos difieren en afinidad y capacidad; adsorción competitiva puede desplazar especies cuando cambia la matriz. Una fibra “universal” no existe para toda mezcla. La selección exige evaluar analitos relevantes, reproducibilidad, estabilidad y sesgo de cobertura.','Una sustancia muy abundante reduce respuesta de otra a igual concentración. Discute competencia y cómo distinguirla de pérdida instrumental.'],
 ['La desorción térmica libera analitos retenidos en un sorbente, pero puede generar transformación o recuperación incompleta. La ruptura ocurre cuando analito atraviesa el lecho durante muestreo. Depende de volumen, humedad, sorbente y compuesto, no solo de duración.','Coloca conceptualmente un segundo tubo de respaldo para evaluar paso del analito. Explica qué evidencia distinguiría ruptura y contaminación.'],
 ['SPME Arrow y extracción dinámica cambian geometría, capacidad y transporte respecto de configuraciones clásicas. Mayor captación no elimina necesidad de calibración. La validación debe cubrir blancos, competencia, rango, tiempos y memoria bajo las condiciones específicas.','Compara configuraciones usando igual matriz y controles, e informa precisión y respuesta de cada compuesto además de señal total.'],
 ['GC-HRMS permite distinguir masas próximas según resolución y exactitud, mientras GC añade separación temporal. Isómeros pueden seguir siendo indistinguibles por masa y necesitar retención o MS/MS. La calidad de identificación depende de evidencia combinada y condiciones de ionización.','Dos compuestos isoméricos tienen idéntica masa exacta. Propón una comparación de retención con estándares para diferenciarlos.'],
 ['GC×GC modula fracciones de una primera columna hacia otra de selectividad distinta, generando datos bidimensionales. La frecuencia de modulación debe representar los picos de primera dimensión. Ganar capacidad de separación añade complejidad en integración, alineamiento y cuantificación.','Un pico de primera dimensión produce varias fracciones moduladas. Explica por qué no deben contarse como compuestos independientes.'],
 ['GC-IMS combina retención cromatográfica con movilidad de iones en gas bajo condiciones definidas. Movilidad depende de interacciones y estructura, y puede haber monómeros, dímeros y efectos de humedad. Un patrón bidimensional no identifica automáticamente una molécula sin referencia.','Una sustancia puede generar varias señales de movilidad según concentración. Evalúa esta posibilidad antes de asignar múltiples analitos.'],
 ['GC-olfatometría relaciona zonas de elución con percepción y requiere un diseño sensorial controlado. Intensidad instrumental y contribución al olor no son equivalentes porque umbrales varían. Evaluación humana exige condiciones éticas y de seguridad y no exposición improvisada a mezclas desconocidas.','Compara un pico abundante con otro pequeño pero perceptible. Explica por qué área cromatográfica no predice por sí sola impacto sensorial.'],
 ['PTR-MS utiliza reacciones ion-molécula, frecuentemente transferencia de protones, para medir gases rápidamente. La química depende de afinidades y condiciones del reactor. Humedad, fragmentación e isobarías pueden complicar interpretación; una masa detectada no es una identificación única.','Dos volátiles producen el mismo ion nominal. Describe cómo resolución, calibración y una técnica separativa ayudarían a resolver la ambigüedad.'],
 ['SIFT-MS selecciona iones reactivos y utiliza cinética de reacciones en un tubo de flujo para inferir concentraciones. Las tasas, tiempos y canales de reacción deben ser conocidos y aplicables. Iones diferentes aportan selectividad complementaria, pero no eliminan toda interferencia.','Compara respuestas con dos iones reactivos y examina si un candidato explica ambas. Revisa condiciones y estándares antes de cuantificar.'],
 ['El agua puede cambiar poblaciones de iones y formación de agregados. La energía de interacción modifica fragmentación y selectividad. Corregir intensidad sin considerar estas rutas puede sesgar concentraciones; deben verificarse patrones bajo humedad y condiciones próximas a las muestras.','Una señal disminuye al aumentar humedad y otra crece. Discute redistribución de iones antes de concluir que cambió la concentración gaseosa.'],
 ['Los métodos directos ofrecen resolución temporal y los cromatográficos añaden separación de mezclas, con tiempos y preparación distintos. La elección depende de la pregunta y de interferencias. Compararlos requiere misma base de unidades y muestreo representativo.','Un pulso breve puede perderse en una muestra integrada para GC. Explica qué información conserva una medición directa y qué confirmación estructural puede faltarle.'],
 ['Las series de referencia permiten normalizar parcialmente retención bajo una convención. Identidad de fase, programa y modo de cálculo deben acompañar el índice. Un intervalo de referencia ayuda a descartar candidatos, pero una coincidencia no sustituye espectro y estándar.','Calcula conceptualmente el índice entre dos alcanos vecinos usando la fórmula correspondiente al modo de operación, sin mezclar tiempos ajustados e índices lineales.'],
 ['La deconvolución separa espectros superpuestos utilizando perfiles temporales y patrones de iones. Coincidencia bibliográfica depende de limpieza y cobertura de referencia. Una puntuación alta no demuestra ausencia de coelución ni distingue todos los isómeros.','Inspecciona iones compartidos y exclusivos de un pico compuesto. Explica cómo un espectro contaminado puede favorecer un candidato incorrecto.'],
 ['Los estándares auténticos aportan comparación de retención y espectro; los isotópicos pueden seguir variación analítica. Su uso requiere pureza, estabilidad y ausencia de interferencias. Una analogía química no garantiza que un patrón sustituto reproduzca partición y recuperación.','Compara un patrón isotópico del analito con un compuesto solo parecido. Indica qué compensaciones exigirían validación adicional.'],
 ['Calibrar gases exige definir fracción molar o concentración, temperatura, presión y trazabilidad del sistema. Dilución, paredes y humedad pueden alterar composición entregada. Una concentración nominal de cilindro no garantiza la misma concentración en la entrada del instrumento.','Convierte conceptualmente ppbv a concentración másica indicando masa molar, T y p. Explica por qué omitir condiciones produce ambigüedad.'],
 ['Blancos de campo, transporte y laboratorio localizan contribuciones diferentes a la señal. Su frecuencia debe permitir detectar variabilidad, no solo un valor inicial. La sustracción automática puede producir negativos o ocultar contaminación fluctuante; requiere criterios explícitos.','Un blanco de transporte alto y uno de laboratorio bajo sugieren investigar recipiente y trayecto. No atribuyas el problema inmediatamente a la fuente MS.'],
 ['Los materiales pueden liberar compuestos y retenerlos para liberación posterior. Arrastre introduce dependencia de muestras previas y debe evaluarse con secuencias apropiadas. Limpieza, acondicionamiento y reemplazo se guían por evidencia y procedimientos del equipo.','Coloca un blanco después de una muestra concentrada y compáralo con uno previo para estimar memoria.'],
 ['Estabilidad y recuperación se evalúan en condiciones reales de almacenamiento y muestreo. Los límites analíticos deben incluir variabilidad de blancos y preparación, no solo ruido electrónico. Un analito perdido antes del detector no se recupera mejorando resolución de masas.','Compara un estándar fresco y otro almacenado en matriz. Distingue degradación, adsorción y respuesta instrumental mediante controles complementarios.'],
 ['La comparación interlaboratorio requiere mensurando, unidades y protocolos suficientemente compatibles. Diferencias pueden surgir de calibración, muestreo o procesamiento. La incertidumbre debe acompañar resultados y las discrepancias investigarse sin asumir que un equipo más costoso es referencia absoluta.','Dos laboratorios discrepan dentro de sus incertidumbres combinadas. Explica cómo evaluar compatibilidad antes de atribuir un sesgo.'],
 ['Alinear perfiles debe conservar identidades y no forzar coincidencias entre señales distintas. La censura por límites de detección difiere de un fallo de integración. Imputaciones alteran estadística y deben respetar separación de entrenamiento y prueba.','Una señal bajo límite no es exactamente cero. Compara tratamientos de censura y analiza sensibilidad de las conclusiones.'],
 ['La normalización compensa variaciones justificadas de cantidad o respuesta; corrección de deriva trata variación temporal. Ambas pueden distorsionar biología si sus supuestos fallan. QC distribuidos y patrones permiten evaluar qué componente se está corrigiendo.','Normalizar por señal total puede ocultar un aumento global real de volátiles. Propón una base alternativa y una comparación de sensibilidad.'],
 ['Un modelo predictivo necesita evaluación en muestras independientes del proceso de selección y ajuste. Debe respetar agrupación por sujeto, sesión o lote y reportar métricas e incertidumbre. La transferencia a otro entorno puede fallar por distribución y condiciones distintas.','Separa una cohorte externa antes de elegir variables. Explica por qué consultar repetidamente su desempeño la convierte en parte del desarrollo.'],
 ['Los patrones candidatos pueden reflejar ambiente, dieta, microbiota o procedimientos, además de la condición estudiada. Un biomarcador exige especificidad y validación para el uso previsto. Asociaciones exploratorias no deben presentarse como diagnósticos ni decisiones clínicas.','Una firma diferencia edificios y coincide con grupos clínicos. Diseña un control ambiental para evaluar confusión antes de una interpretación biológica.'],
 ['En alimentos, plantas y ambiente, perfiles volátiles responden a maduración, estrés, metabolismo y procesos físicos. Muestreo debe reflejar escala temporal y espacial pertinente. Un compuesto puede ser indicador contextual sin ser exclusivo del proceso.','Compara frutos a distinta madurez controlando temperatura y almacenamiento. Distingue emisión metabólica de cambios de partición.'],
 ['Un protocolo biológico define finalidad, participantes o muestras, consentimiento y protección de información según revisión institucional aplicable. Debe distinguir investigación exploratoria y aplicación validada. La recolección de aliento u otras muestras no se improvisa solo por ser no invasiva.','Especifica variables necesarias y minimiza datos identificables. Señala quién autoriza usos secundarios y cómo se documentan.'],
 ['La reproducibilidad necesita conectar archivos crudos, muestras, condiciones y procesamiento. Unidades, definiciones de picos y parámetros deben ser explícitos. Código versionado no basta si faltan calibraciones, blancos o metadatos de conservación.','Construye un diccionario con tiempos, recipientes, caudal, humedad y lote. Explica cómo permite investigar una señal inesperada.'],
 ['La defensa integra pregunta, diseño, evidencia química y validación estadística. Debe explicitar incertidumbres y alternativas y distinguir utilidad potencial de desempeño demostrado. El siguiente experimento se elige para resolver una limitación concreta, no solo para aumentar número de señales.','Presenta una conclusión con identidad o nivel de anotación, efecto, controles y alcance. Propón una validación externa o química que pueda refutarla.']
 ]},
 'metabolomica': {context:'La metabolómica estudia conjuntos de metabolitos bajo una cobertura determinada por muestreo, extracción y plataforma. Una característica instrumental no equivale automáticamente a un metabolito: aductos, isótopos, fragmentos e interferencias pueden multiplicar señales. La interpretación de posgrado debe integrar calidad analítica, confianza de identificación y diseño estadístico. Los cambios de abundancia no demuestran flujo ni causalidad, y los hallazgos necesitan validación independiente antes de extrapolarse.',reading:[['EMBL-EBI · Introducción a metabolómica (inglés)','https://www.ebi.ac.uk/training/online/courses/metabolomics-introduction/'],['EMBL-EBI · Diseño del estudio (inglés)','https://www.ebi.ac.uk/training/online/courses/metabolomics-introduction/designing-a-metabolomics-study/'],...statistics],lessons:[
 ['Un enfoque dirigido define analitos y desempeño antes del análisis; uno no dirigido explora muchas señales con cobertura parcial. La cuantificación absoluta exige calibración adecuada y no se obtiene automáticamente de áreas relativas. Descubrimiento y confirmación responden preguntas diferentes y pueden requerir fases separadas.','Diseña una exploración de señales y una fase posterior de confirmación de candidatos con patrones auténticos. Explica qué cambia en la evidencia requerida.'],
 ['Muestreo, aleatorización y controles evitan confundir biología con procesamiento. Distribuir grupos a lo largo de extracción y adquisición reduce confusión, pero no corrige un diseño completamente confinado por lotes. Mezclas QC evalúan reproducibilidad técnica y no reemplazan réplicas biológicas independientes.','Si todos los controles se miden un día y casos otro, grupo y lote son inseparables. Propón una distribución prospectiva más informativa.'],
 ['LC-MS, GC-MS y RMN observan subconjuntos diferentes por polaridad, volatilidad, sensibilidad y preparación. Combinar técnicas puede ampliar cobertura, pero también introduce desafíos de normalización e identificación. No se deben sumar indiscriminadamente señales de plataformas como si fueran moléculas independientes.','Un metabolito puede generar varias señales en MS y una región solapada en RMN. Explica cómo evitar contar múltiples veces la misma entidad.'],
 ['Detectar picos, alinear y normalizar son operaciones con supuestos. Cambios de parámetros alteran la tabla final; el procesamiento debe conservar trazabilidad desde cada característica a datos crudos. La normalización no debe eliminar una variación global biológicamente relevante ni aprender de la prueba.','Compara normalización por suma total y por patrón interno cuando una gran fracción de metabolitos cambia. Explica posibles distorsiones.'],
 ['Anotar propone identidades con evidencia; identificar requiere correspondencia suficientemente específica con referencias. Masa exacta por sí sola no distingue todos los isómeros. Documenta aducto, fórmula, espectro, retención y nivel de confianza sin presentar candidatos como certezas.','Dos isómeros comparten fórmula y masa. Indica qué comparación con patrón auténtico y qué propiedad adicional aumentaría confianza.'],
 ['La inferencia combina pruebas, tamaños de efecto y estructura de datos. Enriquecimiento de rutas depende del universo medido y de la calidad de anotaciones. Reproducibilidad exige datos, parámetros y código; una ruta “significativa” no demuestra activación causal.','Compara una lista de señales con una lista de metabolitos identificados. Explica por qué duplicados y anotaciones ambiguas alteran el enriquecimiento.'],
 ['Una hipótesis debe especificar población, contraste y resultado. El estimando define qué efecto se busca, mientras confusores pueden explicar asociaciones alternativas. Elegir covariables exige conocimiento del diseño; ajustar indiscriminadamente por mediadores o colisionadores puede introducir sesgo.','Distingue asociación entre tratamiento y metabolito de efecto causal. Dibuja un esquema de variables y explica qué confusores medirías.'],
 ['El tamaño muestral depende de efecto relevante, variabilidad y criterio de error, además de multiplicidad y pérdidas. La potencia de un solo metabolito no caracteriza toda una plataforma. Datos piloto deben evaluarse con cautela porque efectos estimados pueden ser inestables.','Compara aumentar réplicas biológicas con repetir inyecciones de las mismas muestras. Explica cuál mejora evidencia sobre variación entre sujetos.'],
 ['Las medidas longitudinales conservan dependencia dentro del sujeto y permiten estudiar trayectorias. Tiempo, tratamiento y pérdida de seguimiento requieren modelado explícito. Tratar visitas como individuos independientes reduce artificialmente incertidumbre y puede contaminar validación predictiva.','Separa entrenamiento y prueba por sujeto, no por visita. Propón un efecto aleatorio o una estructura de correlación para el análisis.'],
 ['Los estudios biológicos requieren revisión ética aplicable, consentimiento y gestión de información identificable. El preregistro distingue decisiones previas de exploratorias; no impide análisis nuevos si se etiquetan claramente. Las muestras y metadatos deben usarse dentro del alcance autorizado.','Redacta un plan que separe análisis confirmatorios y exploratorios e indique cómo se compartirían metadatos desidentificados, sujeto a aprobación institucional.'],
 ['El apagado busca detener transformaciones rápidamente sin introducir pérdidas o cambios químicos importantes. La extracción debe recuperar familias de interés y controlar temperatura y tiempo. Un protocolo adecuado para una matriz puede alterar otra; no existe extracción exhaustiva universal.','Compara retrasos antes del procesamiento y evalúa señales sensibles al tiempo. Distingue variación preanalítica de diferencia biológica.'],
 ['Transporte y almacenamiento pueden causar degradación, oxidación o cambios por ciclos de congelación. La estabilidad debe evaluarse para analitos y matrices relevantes, incluyendo autosampler. Un control estable de una sustancia no demuestra estabilidad de todas las características.','Diseña una comparación de tiempos de espera con alícuotas independientes y controles de preparación para no confundir efectos.'],
 ['Los estándares isotópicos pueden seguir pérdidas y variaciones si se comportan suficientemente como el analito. Momento de adición, pureza y solapamiento isotópico importan. Un único estándar no corrige de igual manera todas las familias químicas de un estudio no dirigido.','Añadir un estándar después de extracción informa respuesta instrumental, pero no recuperación anterior. Define el objetivo antes de elegir el punto de adición.'],
 ['La matriz puede suprimir o aumentar ionización por coeluyentes y competencia. Dilución y limpieza reducen ciertos efectos, pero pueden disminuir detectabilidad. Comparar extractos fortificados y soluciones de referencia permite investigar respuesta de matriz bajo condiciones controladas.','Una señal aumenta al diluir una muestra pese a reducir analito. Discute supresión iónica y cómo comprobarla con controles apropiados.'],
 ['LC-HRMS aporta separación y masa con alta resolución según configuración. DDA selecciona precursores y puede perder especies débiles; DIA fragmenta ventanas y requiere separar contribuciones. La cobertura de MS/MS y la especificidad de asignación dependen del método.','Compara una señal sin MS/MS en DDA con espectros compuestos en DIA. Explica por qué mayor cobertura no equivale automáticamente a identificación inequívoca.'],
 ['GC-MS necesita volatilidad y estabilidad térmica, a menudo mediante derivatización. La reacción preparativa puede ser incompleta o generar múltiples productos. Retención, espectro y comportamiento de estándares deben evaluarse junto con blancos y controles de reacción.','Un metabolito aparece como dos derivados. Propón cómo reconocerlo y evitar interpretarlos como cambios de dos metabolitos independientes.'],
 ['La RMN cuantitativa relaciona integrales con cantidad bajo adquisición y relajación adecuadas. Las técnicas 2D mejoran asignación, pero sus intensidades no siempre se interpretan directamente como concentraciones. Solapamiento, pH y temperatura modifican señales.','Un retardo de relajación insuficiente puede sesgar integrales de núcleos con T₁ distintos. Explica cómo evaluar esa fuente de error.'],
 ['Cobertura, sensibilidad y selectividad varían entre plataformas y clases químicas. Más características no significa necesariamente más metabolitos identificados. Una comparación pertinente considera muestras equivalentes, blancos, reproducibilidad y grado de confianza de las asignaciones.','Evalúa dos plataformas por número de metabolitos confirmados y variabilidad de QC, además del número bruto de señales.'],
 ['Blancos detectan contaminación; mezclas QC monitorizan estabilidad; series de dilución investigan respuesta y posibles saturaciones. Cada control responde a una pregunta. Filtrar características necesita criterios documentados y sensibilidad a distintos umbrales, evitando decisiones orientadas por el resultado biológico.','Una señal intensa en blancos y muestras puede ser contaminación. Establece una regla justificada usando variabilidad y proporciones, no solo presencia.'],
 ['Aleatorizar y distribuir QC reduce confusión entre orden y grupo. El control entre lotes necesita material comparable y registros de cambios. Una corrección estadística no recupera información si lote y biología están completamente confundidos.','Distribuye casos y controles en cada lote y coloca referencias repetidas. Explica qué diferencia habría si un lote contiene un solo grupo.'],
 ['La deriva puede ser gradual, abrupta o específica de clases químicas. Los criterios de exclusión deben responder a calidad y fijarse sin seleccionar resultados favorables. Corregir sobre QC requiere suficientes puntos y no justifica extrapolar fuera del intervalo cubierto.','Un salto de respuesta después de limpieza de fuente puede requerir tratar segmentos separadamente. Comprueba la corrección con controles no usados para ajustarla.'],
 ['Los materiales de referencia ayudan a comparar desempeño y sostener trazabilidad cuando son pertinentes al mensurando. Material compartido no implica que toda señal tenga valor certificado. Debe distinguirse comparación relativa de cuantificación trazable de analitos definidos.','Una mezcla QC interna permite vigilar repetibilidad, pero no asigna automáticamente concentraciones certificadas a todas sus señales.'],
 ['La detección identifica estructuras de señal y la deconvolución intenta separar contribuciones superpuestas. Parámetros de ancho, ruido y resolución afectan falsos positivos y pérdidas. Revisar datos crudos de ejemplos representativos permite comprobar que la tabla no sea un artefacto del procesamiento.','Dos picos parcialmente solapados pueden fusionarse con parámetros inadecuados. Compara integración automática y evidencia cromatográfica.'],
 ['Alinear vincula señales compatibles entre muestras; agrupar aductos e isótopos evita contar una molécula varias veces. Tolerancias excesivas fusionan especies y demasiado estrictas fragmentan grupos. Correlación de intensidad ayuda, pero no prueba identidad compartida.','[M+H]⁺ y [M+Na]⁺ pueden corresponder a una misma molécula. Verifica diferencia de masa, retención y comportamiento antes de agrupar.'],
 ['Los datos faltantes pueden reflejar valores bajos, fallos de integración o ausencia estructural. Cada mecanismo requiere tratamiento distinto. Reemplazar todo por cero o por un valor pequeño cambia varianzas y distancias; la evaluación debe incluir análisis de sensibilidad.','Una señal ausente solo en un lote puede ser problema técnico. Investiga adquisición antes de interpretarla como ausencia biológica.'],
 ['Normalización y corrección de lote deben usar información permitida por el diseño de evaluación. Aprender parámetros con todos los datos introduce fuga. También puede eliminarse señal biológica real si se supone erróneamente que todas las distribuciones deben ser iguales.','Ajusta transformaciones en entrenamiento y aplícalas a prueba sin recalcularlas. Distingue este procedimiento de corregir una secuencia analítica con QC predefinidos.'],
 ['Masa exacta y patrones isotópicos restringen fórmulas, pero requieren carga y aducto correctos y tolerancias justificadas. Varias fórmulas pueden caber en el intervalo de error. La plausibilidad química y evidencia adicional deben acompañar la coincidencia numérica.','Calcula error en ppm como diferencia dividida por masa de referencia por un millón. Explica por qué un error pequeño no identifica un isómero.'],
 ['La comparación MS/MS depende de energía, instrumento y especie precursora. Una biblioteca puede no cubrir todos los candidatos y sus puntuaciones no son probabilidades universales. Examina fragmentos diagnósticos, pérdidas y alternativas, e informa condiciones de comparación.','Un buen score con pocos fragmentos compartidos puede ser poco específico. Revisa qué evidencia distingue el candidato de un análogo.'],
 ['Un estándar auténtico analizado bajo condiciones comparables permite contrastar retención y espectro. La coincidencia debe evaluarse con tolerancias y posibles coeluciones. Una adición a muestra aporta evidencia útil, pero puede seguir requiriendo separación de isómeros cercanos.','Compara muestra, estándar y mezcla de ambos. Explica qué confirma la coincidencia y qué ambigüedad puede persistir.'],
 ['Los niveles de confianza comunican cuánta evidencia respalda una asignación. Debe citarse el esquema usado y conservar candidatos alternativos. Los desconocidos pueden ser reproducibles y relevantes sin nombre estructural; no deben recibir identidades por conveniencia interpretativa.','Reporta una característica por m/z y retención cuando solo existe una fórmula tentativa. Distingue claramente anotación de identificación confirmada.'],
 ['Los modelos mixtos representan dependencia dentro de sujetos o bloques. Las pruebas múltiples requieren controlar una tasa de error adecuada, sin reemplazar estimación de efectos. Covariables y transformaciones deben justificarse por diseño y diagnósticos, no por lograr significación.','Analiza visitas repetidas con un término por sujeto y reporta efecto e intervalo. Distingue corrección por multiplicidad de ajuste por confusores.'],
 ['PCA explora variación; PLS usa relación con respuestas y puede sobreajustar en dimensiones altas. Scores separados no demuestran predicción externa. El número de componentes y el preprocesamiento deben seleccionarse dentro de validación compatible con sujetos y lotes.','Un PLS-DA puede separar etiquetas aleatorias en entrenamiento. Usa evaluación independiente para distinguir aprendizaje útil de ajuste al ruido.'],
 ['Validación anidada separa selección y estimación; permutaciones estudian asociación bajo intercambiabilidad; una cohorte externa examina transferencia. Las tres responden preguntas distintas. Deben conservarse sujetos o bloques juntos y explicitar diferencias entre cohortes.','Una cohorte externa con otro instrumento prueba también variación técnica. Interpreta una caída de rendimiento sin atribuirla únicamente a biología.'],
 ['La confusión puede producir asociaciones sin efecto causal directo. Reproducir una asociación fortalece evidencia, pero no elimina automáticamente sesgos compartidos. Perturbaciones, temporalidad y mecanismos aportan información complementaria y requieren diseños específicos.','Una dieta afecta exposición y metabolitos; ajustar o estratificar exige medirla adecuadamente. Explica qué inferencia sigue siendo limitada.'],
 ['El enriquecimiento depende del conjunto de referencia y de cobertura instrumental. Rutas grandes, redundancias y anotaciones ambiguas pueden sesgar resultados. El universo apropiado debe reflejar qué metabolitos podían detectarse y analizarse, no todo un catálogo sin restricciones.','Compara enriquecimiento usando universo global y universo medido. Explica cómo una cobertura preferente de lípidos puede afectar conclusiones.'],
 ['Los trazadores siguen incorporación isotópica y ayudan a inferir flujos con modelos y balances. Distribuciones isotopológicas dependen de tiempo, fuentes y compartimentos. Una mayor fracción marcada no equivale siempre a mayor flujo absoluto sin información de tamaños de pool y suministro.','Compara enriquecimiento de un metabolito en dos tiempos. Identifica datos necesarios para diferenciar recambio y acumulación.'],
 ['Integrar ómicas requiere alinear muestras, escalas y mecanismos de ausencia. Las asociaciones entre capas pueden reflejar factores compartidos y no regulación directa. La dimensión aumenta riesgo de sobreajuste y demanda validación y objetivos claros.','Relaciona ARN, proteína y metabolito sin asumir proporcionalidad. Propón una perturbación funcional para evaluar una conexión candidata.'],
 ['Las redes metabólicas representan reacciones y restricciones, pero su validez depende de anotaciones y compartimentos. La validación funcional comprueba predicciones mediante perturbaciones o medidas específicas. Un enlace de red o correlación no establece por sí solo transferencia material directa.','Un bloqueo enzimático predice cambios aguas arriba y abajo. Explica cómo un bypass o transporte puede modificar esa predicción.'],
 ['El plan de datos define identificadores, formatos, respaldo, permisos y metadatos antes de adquirir. Debe permitir conectar muestra biológica, preparación y archivo instrumental sin exponer identidades personales. Una tabla sin diccionario dificulta reutilización y auditoría.','Define campos para lote, orden, matriz y unidades, separando información sensible del identificador analítico compartible.'],
 ['Un repositorio y un entorno versionado permiten reconstruir el análisis, pero requieren datos suficientes y dependencias explícitas. Registra parámetros, semillas y exclusiones. Formatos abiertos facilitan intercambio sin sustituir la conservación de archivos originales cuando corresponde.','Entrega un script que reconstruya tabla y figuras desde entradas documentadas, junto con versiones y un pequeño ejemplo verificable.'],
 ['La revisión del protocolo examina si diseño y controles pueden responder la pregunta antes del coste experimental. Debe buscar confusión, sesgos de selección y criterios ambiguos. Cambios posteriores se documentan para distinguir decisiones confirmatorias y exploratorias.','Pide a un revisor identificar dónde se perdería trazabilidad entre muestra y resultado. Corrige el protocolo antes de adquirir nuevas muestras.'],
 ['Defender resultados implica mostrar evidencia, alternativas y alcance, no solo diferencias significativas. La incertidumbre de identificación y medición se combina con limitaciones del diseño. Las aplicaciones propuestas deben corresponder al grado de validación y población estudiada.','Redacta una conclusión con hallazgo, tamaño de efecto, limitación principal y siguiente prueba. Evita presentar un candidato exploratorio como herramienta clínica validada.']
 ]},
 'cuantica-computacional': {context:'La mecánica cuántica representa estados mediante funciones y observables mediante operadores. Sus resultados son probabilísticos y dependen de condiciones de contorno, simetría y aproximaciones. Un cálculo molecular combina modelo físico, método numérico y elección de parámetros; obtener convergencia no garantiza exactitud química. Es indispensable comprobar unidades, carga, espín y estabilidad de la solución y comparar con evidencia o métodos independientes.',reading:[['MIT OCW · Physical Chemistry (inglés)','https://ocw.mit.edu/courses/5-61-physical-chemistry-fall-2007/']],lessons:[
 ['La ecuación estacionaria Hψ=Eψ relaciona estados y energías cuando el Hamiltoniano no depende explícitamente del tiempo. Los operadores observables tienen propiedades matemáticas que aseguran resultados reales. Las soluciones requieren normalización y condiciones de contorno físicamente pertinentes.','Distingue el operador Hamiltoniano de su autovalor E. Explica por qué una función arbitraria no es necesariamente un estado de energía definida.'],
 ['Los modelos sencillos aíslan rasgos como confinamiento, vibración o rotación. Permiten comprender cuantización y reglas de selección, pero no reproducen todos los detalles moleculares. Debe identificarse qué grados de libertad se conservan y qué interacciones se omiten.','Compara niveles de partícula en caja y oscilador armónico: su separación energética no crece de la misma forma con el número cuántico.'],
 ['Los orbitales moleculares describen funciones monoelectrónicas dentro de aproximaciones. La combinación depende de simetría, energía y solapamiento; ocupaciones aportan información sobre enlace y magnetismo. Un orbital individual no es una trayectoria y su representación depende del modelo utilizado.','Explica cómo ocupar un orbital antienlazante puede disminuir orden de enlace. Relaciona el argumento con una comparación de especies isoelectrónicas apropiada.'],
 ['Métodos ab initio aproximan la función electrónica; DFT trabaja con la densidad y requiere aproximar intercambio-correlación. Coste y error dependen del problema. Ningún funcional o método es universal: interacciones débiles, multirreferencia y estados excitados plantean dificultades diferentes.','Compara dos métodos para una energía relativa y revisa sensibilidad al conjunto de base. No interpretes coincidencia entre métodos como prueba definitiva.'],
 ['Optimizar geometría busca puntos estacionarios de una superficie. El análisis de frecuencias clasifica mínimos y puntos silla dentro de la aproximación armónica. Frecuencias imaginarias pueden revelar inestabilidad o problemas numéricos; modos muy blandos requieren interpretación cuidadosa.','Un mínimo ideal tiene todas las curvaturas vibracionales positivas; un estado de transición de primer orden presenta una negativa. Revisa el modo correspondiente.'],
 ['Las energías calculadas dependen de nivel teórico, geometría y correcciones térmicas. Energía electrónica, entalpía y energía libre no son intercambiables. Comparar reacciones exige estados y referencias consistentes, además de considerar error sistemático y posibles cancelaciones.','Dos conformaciones pueden cambiar de orden al incluir entropía. Explica qué magnitud corresponde a poblaciones de equilibrio a temperatura dada.'],
 ['Álgebra lineal organiza funciones como vectores y operadores como matrices. Autovectores identifican estados asociados a autovalores; ortogonalidad y normalización facilitan expansión. Una base truncada introduce aproximación, y matrices mal condicionadas pueden generar dificultades numéricas.','Diagonaliza conceptualmente una matriz diagonal 2×2 y relaciona sus entradas con autovalores. Explica qué cambia al introducir un acoplamiento fuera de la diagonal.'],
 ['La densidad de probabilidad se obtiene de ψ*ψ y debe integrar a uno. El valor esperado promedia resultados posibles con el estado, sin garantizar que una medición individual coincida con él. Fase y amplitud tienen efectos distintos en observables e interferencia.','Para una partícula confinada, integra la densidad sobre una región para obtener probabilidad. Comprueba que sea adimensional y esté entre cero y uno.'],
 ['El conmutador mide dependencia del orden de aplicar operadores. Observables compatibles pueden compartir una base de estados; relaciones de incertidumbre se vinculan con conmutadores. La incertidumbre cuántica del estado no es equivalente al error técnico del instrumento.','Posición y momento no conmutan. Explica por qué mejorar un aparato no elimina la dispersión intrínseca impuesta por el estado.'],
 ['El método variacional optimiza una función de prueba y, bajo condiciones apropiadas, da una cota superior a la energía fundamental. Perturbación trata correcciones pequeñas respecto de un problema resuelto. Degeneración o cambios fuertes pueden invalidar expansiones simples.','Mejora una familia de funciones de prueba y observa energía variacional. Explica por qué una energía menor no garantiza que todas las propiedades mejoren igual.'],
 ['La partícula en caja impone confinamiento y condiciones de contorno que producen niveles discretos. Energías crecen como n²/L² en el modelo unidimensional infinito. La energía fundamental no es cero y los nodos aumentan con excitación.','Duplicar L reduce las energías a la cuarta parte. Relaciona este resultado con deslocalización, sin trasladarlo literalmente a cualquier molécula.'],
 ['El oscilador armónico aproxima vibración cerca del mínimo; el rotor rígido aproxima rotación sin deformación. Sus niveles y reglas de transición dependen de parámetros distintos. Anharmonicidad y distorsión centrífuga producen desviaciones a energías altas.','Aumentar masa reducida disminuye frecuencia vibracional para constante de fuerza fija. Usa sustitución isotópica como aplicación conceptual.'],
 ['El átomo hidrogenoide permite soluciones analíticas para un electrón en potencial coulombiano. Los números cuánticos organizan estados; el espín es una propiedad intrínseca adicional. Átomos multielectrónicos requieren considerar repulsión y antisimetría, por lo que no conservan todas las degeneraciones.','Compara H y He⁺ mediante carga nuclear. Explica por qué el helio neutro no se resuelve simplemente duplicando electrones independientes de hidrógeno.'],
 ['Las reglas de selección dependen del operador de transición y de la simetría de estados. Una transición prohibida dentro de una aproximación puede adquirir intensidad por otros mecanismos. Interpretar espectros requiere considerar poblaciones, degeneraciones, ensanchamiento y entorno.','Una ausencia de banda puede responder a selección o baja población. Propón información adicional para distinguir estas causas.'],
 ['El conjunto de base limita la flexibilidad de la representación electrónica. Funciones difusas y de polarización responden a necesidades distintas. Convergencia de base y convergencia del algoritmo son pruebas separadas; aniones e interacciones débiles pueden exigir especial atención.','Compara una energía de interacción con bases crecientes y discute posible error por superposición de base. No confundas más funciones con exactitud garantizada.'],
 ['La correlación electrónica representa efectos no recogidos completamente en una descripción de campo medio. Correlación dinámica y problemas multirreferencia requieren tratamientos diferentes. El error depende de la propiedad y del tipo de enlace, no solo del tamaño molecular.','Una ruptura de enlace puede dificultar un método monorreferencia. Explica por qué un buen resultado cerca del mínimo no asegura una curva correcta completa.'],
 ['Solvente y conformaciones modifican energías y poblaciones. Los modelos continuos omiten detalles específicos que una representación explícita puede necesitar. Un estado de transición debe conectar reactivos y productos relevantes; hallar una frecuencia imaginaria no identifica automáticamente la ruta deseada.','Compara una única geometría en fase gaseosa con un conjunto conformacional en solución. Señala qué diferencias podrían cambiar una predicción de reactividad.'],
 ['Un cuaderno reproducible registra entradas, versiones, métodos y criterios de convergencia junto con resultados. Comparar con experimento requiere igualar condiciones y magnitudes. Deben conservarse cálculos fallidos y alternativas para entender sensibilidad y evitar selección de resultados favorables.','Documenta carga, multiplicidad, base y solvente de una optimización. Indica cómo otra persona verificaría que el mínimo obtenido es el relevante.']
 ]},
 'bioquimica-avanzada': {context:'La bioquímica relaciona estructura molecular, transformación de energía y regulación en sistemas abiertos. Concentraciones, localización y disponibilidad de cofactores condicionan reacciones que en un tubo pueden comportarse de otra forma. Un resultado debe interpretarse a la escala medida: actividad de una enzima aislada, abundancia de metabolito y flujo de una ruta son magnitudes distintas. La evidencia mecanística combina perturbaciones, controles y medidas complementarias.',reading:[['MIT OCW · General Biochemistry (inglés)','https://ocw.mit.edu/courses/7-05-general-biochemistry-spring-2020/']],lessons:[
 ['La unión proteína-ligando depende de complementariedad, solvatación y cambios conformacionales. Afinidad describe equilibrio; constantes de asociación y disociación describen rapidez. Ocupación de sitios depende de concentración libre, y no toda unión conduce a actividad biológica.','Para un sitio simple, θ=[L]/(Kd+[L]). Explica por qué usar ligando total puede fallar si la proteína secuestra una fracción importante.'],
 ['Las enzimas se regulan mediante efectores, modificaciones, disponibilidad y localización. Regulación alostérica puede producir respuestas no hiperbólicas. Cambios de abundancia y cambios de actividad específica no son equivalentes; ambos pueden alterar capacidad de una ruta.','Una actividad aumenta sin cambiar cantidad de proteína. Propón regulación postraduccional o alostérica y una prueba que distinga alternativas.'],
 ['Las rutas centrales conectan oxidación de nutrientes, producción de precursores y regeneración de cofactores. Acoplamiento permite impulsar pasos desfavorables. El balance energético depende de condiciones y transporte; ATP no se interpreta correctamente solo mediante una energía estándar aislada.','Relaciona oxidación de un sustrato con transferencia de electrones y síntesis de ATP, distinguiendo fosforilación a nivel de sustrato y acoplamiento a gradientes.'],
 ['La regulación metabólica coordina tejidos y compartimentos según señales y demanda. Un paso irreversible puede participar en control, pero este suele distribuirse entre varios procesos. Una concentración elevada puede reflejar producción aumentada o consumo disminuido.','Si acumula un intermediario, propón dos explicaciones opuestas de flujo. Indica qué medición temporal o trazador ayudaría a diferenciarlas.'],
 ['Diseñar un ensayo exige relacionar una señal con la transformación de interés y controlar fondo, linealidad y estabilidad. Sustratos, cofactores y condiciones deben ser pertinentes. Un ensayo acoplado requiere que la reacción indicadora no limite la velocidad medida.','Una señal de NADH puede informar una reacción acoplada. Verifica que aumentar la enzima indicadora no cambie la velocidad aparente del proceso principal.'],
 ['Los datos bioquímicos requieren normalización compatible con la pregunta y controles de matriz. Réplicas biológicas y técnicas responden a variabilidades diferentes. Significación estadística no establece mecanismo: deben considerarse efectos de viabilidad, extracción y composición celular.','Un metabolito por miligramo de proteína aumenta porque disminuye la proteína total. Examina resultados absolutos y normalizados antes de inferir síntesis acelerada.'],
 ['El plegamiento equilibra interacciones y entropía en un entorno específico. Chaperonas y control de calidad ayudan a evitar agregación, sin codificar una nueva secuencia. Desnaturalización no implica necesariamente ruptura de enlaces peptídicos y puede ser reversible o irreversible según condiciones.','Compara pérdida de actividad por desnaturalización y por inhibición reversible. Propón controles para distinguir ambas causas.'],
 ['Carbohidratos, lípidos y membranas participan en reserva, reconocimiento y compartimentalización. La organización de bicapas depende de anfipaticidad y composición. Fluidez y permeabilidad no son equivalentes y cambian con temperatura, insaturación y otros componentes.','Compara una membrana enriquecida en cadenas saturadas con otra más insaturada a igual temperatura, indicando que composición completa también influye.'],
 ['Purificar separa biomoléculas por propiedades como tamaño, carga y afinidad. Rendimiento y pureza deben monitorizarse por etapa; una banda dominante no garantiza actividad o identidad. La caracterización integra composición, estructura y función.','Calcula actividad específica antes y después de una purificación. Explica cómo puede aumentar mientras disminuye la actividad total recuperada.'],
 ['La energía libre de unión integra contribuciones entálpicas y entrópicas. Cooperatividad describe dependencia entre ocupaciones o estados y puede generar curvas sigmoidales. El coeficiente de Hill resume comportamiento en un intervalo, pero no siempre equivale al número de sitios.','Compara una curva hiperbólica y una sigmoidal sin asignar automáticamente diferente número de ligandos. Propón un modelo de estados.'],
 ['La señalización combina reconocimiento, transmisión, amplificación y terminación. Segundos mensajeros cambian localmente y se regulan por síntesis y eliminación. Una respuesta sostenida puede deberse tanto a activación como a fallo de apagado; la dinámica importa.','Un pulso de calcio y un aumento prolongado pueden tener efectos diferentes. Explica por qué una medición final única pierde información.'],
 ['El metabolismo nitrogenado conecta aminoácidos, nucleótidos y eliminación de nitrógeno. Transferir grupos amino y liberar amonio son procesos distintos. Las rutas requieren balances de átomos y energía y varían según organismo y tejido.','Sigue el nitrógeno de un aminoácido hacia un producto de excreción en un esquema conceptual. No confunda ese seguimiento con el del esqueleto carbonado.'],
 ['Compartimentos mantienen ambientes y gradientes que regulan reactividad. El transporte puede consumir energía o aprovechar gradientes; concentración total celular oculta distribuciones locales. Las lanzaderas transfieren equivalentes sin necesariamente mover la misma molécula entre membranas.','Explica por qué medir NADH total no determina directamente el estado redox de cada compartimento.'],
 ['Regulación transcripcional modifica producción de componentes y la postraduccional cambia propiedades de proteínas existentes. Sus escalas temporales pueden diferir. Expresión de ARN, proteína y actividad no mantienen una relación fija por degradación, modificaciones y contexto.','Un aumento de ARN sin aumento de actividad puede reflejar control traduccional o proteína inactiva. Propón medidas complementarias.'],
 ['La inhibición se caracteriza por modelos cinéticos y condiciones, no solo por caída de señal. Ensayos acoplados pueden ser afectados en la reacción principal o indicadora. Agregación, interferencia óptica y cambios de pH también pueden simular inhibición.','Una sustancia disminuye absorbancia sin inhibir la enzima. Diseña un control sin enzima y otro del sistema indicador.'],
 ['Los balances energéticos y de masa restringen flujos posibles. La concentración de intermediarios no mide directamente flujo; este requiere información temporal, consumo, producción o trazadores. Rutas paralelas y ciclos pueden dar balances globales semejantes.','Dos células con igual concentración de lactato pueden producirlo a velocidades diferentes. Explica qué dato de tasa permitiría distinguirlas.'],
 ['Los controles biológicos deben separar tratamiento, manipulación y variación basal. Aleatorización y replicación independiente reducen confusión. Vehículo, viabilidad y condiciones de cultivo pueden alterar metabolitos y actividad, por lo que deben registrarse y evaluarse.','Si un tratamiento reduce señal y viabilidad a la vez, discute por qué no demuestra inhibición específica de una ruta.'],
 ['La lectura crítica conecta pregunta, diseño, medición y alcance de conclusiones. Examina tamaño de efecto, controles, incertidumbre y reproducibilidad. Una correlación coherente con una ruta no demuestra causalidad sin evidencia adicional de perturbación y mecanismo.','Identifica en un estudio qué se midió directamente y qué se infirió. Propón una prueba que pudiera refutar la explicación principal.']
 ]},
 'ambiental-avanzada': {context:'El destino ambiental de una sustancia depende de forma química, medio y escalas de tiempo. Concentración total, fracción biodisponible y exposición representan preguntas diferentes. Los balances conectan fuentes, transporte, transformación y almacenamiento; cada compartimento requiere parámetros y datos pertinentes. Un modelo ambiental debe declarar límites espaciales y temporales y no convertir correlaciones o valores genéricos en predicciones locales sin evaluación.',reading:[...general,['EPA · Variación de coeficientes de partición (inglés)','https://www.epa.gov/radiation/understanding-variation-partition-coefficient-kd-values']],lessons:[
 ['La especiación distingue formas químicas que pueden tener diferente movilidad y reactividad. Biodisponibilidad depende además de organismo y vía de exposición. pH, ligandos y condiciones redox alteran fracciones, por lo que un metal total no describe completamente comportamiento.','Compara metal disuelto libre, complejado y asociado a partículas. Explica qué medirías para evaluar una hipótesis de disponibilidad.'],
 ['Transporte incluye advección, difusión y dispersión; partición distribuye sustancias entre fases. Una relación de equilibrio local puede ser inadecuada cuando intercambio es lento. El destino requiere balance de masa y velocidades, además de coeficientes de distribución.','Un compuesto puede adsorberse fuertemente y aun movilizarse unido a coloides. Distingue transporte de fase disuelta y particulada.'],
 ['Degradación cambia estructura química y persistencia expresa permanencia bajo condiciones definidas. Pérdida de concentración puede deberse a dilución o transferencia, no destrucción. Deben considerarse productos de transformación, que pueden conservar movilidad o peligrosidad.','Una disminución en agua junto con aumento en sedimento puede indicar redistribución. Propón un balance que evite confundirla con degradación.'],
 ['Procesos fotoquímicos dependen de luz absorbida, sensibilizadores y competidores; procesos redox, de aceptores, donadores y condiciones. La velocidad en laboratorio puede diferir del campo por atenuación, matriz y transporte. Es necesario identificar especies y rutas relevantes.','Compara fotólisis en agua clara y turbia. Explica el papel de penetración de luz y de materia orgánica sin asumir un efecto único.'],
 ['Monitorear exige definir objetivo, sitios, frecuencia y variables auxiliares. Muestreo puntual puede no representar episodios o ciclos. Límites analíticos y conservación deben ser adecuados al mensurando, y el diseño debe permitir separar cambio real y variabilidad.','Para detectar descargas episódicas, compara un muestreo mensual puntual con un diseño temporal dirigido por eventos.'],
 ['Tratar contaminación puede separar, transformar o inmovilizar; cada opción tiene residuos y límites. Prevención reduce generación en origen. Evaluar tecnología requiere balances y productos secundarios, no solo porcentaje de remoción de la fase inicial.','Una adsorción eficaz traslada contaminantes a un sólido. Incluye gestión y regeneración del sorbente en la evaluación.'],
 ['El sistema carbonato vincula CO₂ disuelto, ácido carbónico y especies bicarbonato/carbonato con pH y alcalinidad. Alcalinidad no equivale a pH ni a carbono total. Intercambio gaseoso y precipitación mineral pueden modificar composición.','Dos aguas con igual pH pueden tener distinta capacidad amortiguadora. Relaciona esa diferencia con alcalinidad y composición.'],
 ['La fotoquímica atmosférica combina emisiones, radiación y reacciones radicalarias. La formación de oxidantes secundarios depende de relaciones no lineales entre precursores. Mezcla, transporte y pérdidas compiten con reacción; emisiones locales no determinan solas la concentración observada.','Explica por qué un contaminante secundario puede alcanzar máximos lejos de su fuente de precursores.'],
 ['Suelos y sedimentos combinan minerales, materia orgánica, poros y agua. Sorción depende de especie, superficie y condiciones; desorción puede ser lenta o presentar histéresis. Un coeficiente obtenido en un material no se traslada automáticamente a otro.','Compara retención de una especie ionizable a dos pH y documenta mineralogía y carbono orgánico antes de extrapolar.'],
 ['Los estados de oxidación de metales influyen en complejación, precipitación y transporte. Condiciones redox pueden ser heterogéneas y no estar equilibradas. Un potencial medido y pH no describen necesariamente todas las especies existentes.','Una muestra puede cambiar especiación durante almacenamiento al contactar aire. Explica por qué conservación forma parte de la medición.'],
 ['Un modelo de cajas representa compartimentos con entradas, salidas y transformaciones. Supone mezcla y parámetros específicos dentro de cada caja. Estado estacionario no significa ausencia de flujos; significa balance neto de acumulación nulo.','Para dM/dt=entrada−salida−degradación, identifica condiciones de estado estacionario y qué cambia después de una descarga.'],
 ['La partición aire-agua-sólido depende de temperatura, especie y convenciones de coeficientes. Las formas ionizadas y neutras pueden comportarse de modo distinto. El equilibrio puede tardar más que el tiempo de residencia, limitando el uso de relaciones estáticas.','Una constante de Henry puede expresarse con diferentes unidades y cocientes. Escribe explícitamente su definición antes de usarla.'],
 ['Un modelo de primer orden puede resumir pérdida bajo condiciones controladas, pero su constante aparente mezcla mecanismos si no se separan. Persistencia en campo depende de disponibilidad y ambiente. Extrapolar semividas exige justificar condiciones comparables.','Para primer orden, t½=ln 2/k. Explica por qué una semivida en suelo seco no se aplica directamente a agua iluminada.'],
 ['Exposición describe contacto y dosis potencial; riesgo combina exposición y efectos dentro de un marco definido. Incertidumbre de parámetros y variabilidad poblacional no son idénticas. La presencia detectable de una sustancia no cuantifica automáticamente un riesgo.','Distingue concentración ambiental, duración de contacto y dosis. Explica qué información falta para pasar de detección a evaluación.'],
 ['Representatividad y conservación deben proteger la forma química de interés. Filtración, recipiente, temperatura y tiempo pueden modificar resultados. Los procedimientos deben validarse para analito y matriz; no existe una conservación universal para todos los contaminantes.','Comparar muestras filtradas y sin filtrar responde preguntas distintas. Define fracción operacional y registra el momento de filtración.'],
 ['Los indicadores resumen propiedades y requieren contexto de interpretación. Trazabilidad conecta mediciones con referencias y condiciones documentadas. Un índice compuesto puede ocultar compensaciones entre variables; conviene conservar y comunicar datos individuales.','Dos muestras con igual índice de calidad pueden diferir en contaminantes relevantes. Revisa componentes antes de concluir equivalencia ambiental.'],
 ['Comparar tratamientos requiere igualar influente, escala y objetivo. Rendimiento, consumo, residuos y estabilidad operacional deben analizarse conjuntamente. Una tecnología eficiente en ensayo corto puede perder desempeño por saturación, ensuciamiento o variación de matriz.','Compara remoción inicial y capacidad acumulada de dos adsorbentes. Explica por qué el porcentaje de una sola prueba no define vida útil.'],
 ['El informe de monitoreo debe presentar diseño, cobertura temporal y espacial, calidad y límites analíticos. No detectar no equivale a ausencia. Las conclusiones deben distinguir tendencia observada, hipótesis causal y límites de extrapolación a lugares no muestreados.','Redacta una conclusión para valores bajo el límite de cuantificación sin sustituirlos automáticamente por cero.']
 ]},
 'quimiometria': {context:'La quimiometría conecta mediciones químicas con modelos estadísticos y decisiones. Filtrado, transformación, escalado y selección de variables influyen tanto como el algoritmo final. Toda operación que aprende de los datos debe respetar la separación entre entrenamiento y evaluación. La validación ha de reflejar el uso previsto: nuevas muestras, sujetos, lotes o instrumentos requieren diseños distintos. Buen desempeño interno no demuestra causalidad ni generalización universal.',reading:statistics,lessons:[
 ['El diseño experimental distribuye tratamientos para estimar efectos con variabilidad controlada. Aleatorización, bloqueo y replicación cumplen papeles diferentes. Las interacciones indican que el efecto de un factor depende del nivel de otro y no se detectan adecuadamente con cambios aislados.','Diseña un factorial 2×2 para pH y temperatura. Compara efecto de temperatura a ambos pH para identificar interacción.'],
 ['Preprocesar puede corregir artefactos o cambiar estructura de datos. Escalar por desviación estándar aumenta peso relativo de variables pequeñas y ruidosas. Los valores faltantes requieren analizar su mecanismo; imputar antes de separar validación puede producir fuga de información.','Compara PCA centrado y autoescalado sobre señales de distinta magnitud. Explica qué pregunta responde cada análisis.'],
 ['PCA construye direcciones ortogonales que maximizan varianza del conjunto procesado. Scores describen muestras y loadings variables. Una separación visual puede deberse a lote o escala; PCA no utiliza clases ni demuestra capacidad predictiva.','Si PC1 separa días de adquisición, revisa deriva antes de interpretarla como diferencia biológica.'],
 ['Agrupamiento depende de distancia, representación y criterio de unión. Los valores atípicos pueden ser errores o variación real y requieren investigación. Eliminar puntos según el resultado deseado sesga conclusiones; documenta criterios y análisis de sensibilidad.','Compara distancias euclídeas antes y después de escalado. Explica por qué pueden cambiar los grupos sin cambiar las mediciones originales.'],
 ['Regresión multivariada relaciona predictores con respuesta; PLS construye componentes orientados a covarianza con Y. El número de componentes debe seleccionarse dentro de validación. Colinealidad, sobreajuste y rango de calibración condicionan predicción.','Un PLS con muchos componentes reduce error de entrenamiento. Usa validación interna para elegir complejidad y reserva prueba final independiente.'],
 ['Validación cruzada estima rendimiento bajo una partición, mientras prueba externa evalúa un conjunto no usado en decisiones. Réplicas del mismo sujeto o lote pueden requerir agrupación. Seleccionar variables con todos los datos antes de validar introduce optimismo.','Mantén todas las réplicas de un sujeto en el mismo bloque. Explica por qué repartirlas aleatoriamente puede inflar precisión.'],
 ['La descomposición en valores singulares expresa una matriz mediante bases ortogonales y valores que ordenan variación. Conecta PCA, reducción de rango y estabilidad numérica. Valores pequeños pueden reflejar redundancia o ruido, pero su eliminación debe responder a la tarea.','Una matriz con columnas casi idénticas es mal condicionada. Relaciona esa redundancia con valores singulares pequeños.'],
 ['Las distribuciones modelan variabilidad y estimación resume parámetros con incertidumbre. Independencia y representatividad sostienen muchas inferencias. La media es sensible a extremos; elegir estadísticas robustas requiere considerar el proceso y no ocultar información relevante.','Compara media y mediana de datos asimétricos e indica cuál representa mejor la pregunta analítica planteada.'],
 ['Diagnósticos de regresión examinan forma funcional, residuos, influencia y varianza. Errores correlacionados o heterogéneos modifican inferencia. Un ajuste visual bueno no reemplaza comprobar si el modelo predice de forma útil y estable fuera de entrenamiento.','Inspecciona residuos ordenados por secuencia de medición para detectar deriva que no aparece al graficarlos solo contra concentración.'],
 ['Programar un análisis requiere versiones, datos originales y transformaciones trazables. Una semilla aleatoria facilita repetición, pero no corrige sesgos del diseño. Automatizar controles y exportar decisiones intermedias permite detectar errores y auditar resultados.','Guarda índices de partición, parámetros y versiones junto con predicciones. Explica cómo reconstruirías exactamente una evaluación posterior.'],
 ['Los diseños factoriales estiman efectos e interacciones; los fraccionados reducen ensayos mediante estructuras de alias. La resolución del diseño limita qué efectos pueden separarse. Su elección depende de hipótesis sobre interacciones y recursos disponibles.','En una fracción factorial, dos efectos confundidos no pueden atribuirse por separado sin información o ensayos adicionales. Propón una ampliación.'],
 ['Las superficies de respuesta aproximan una respuesta local mediante términos lineales, cuadráticos e interacciones. Un óptimo matemático puede estar fuera de región válida o ser un punto silla. Confirmación experimental y restricciones físicas son indispensables.','Un modelo predice máxima respuesta fuera del rango estudiado. Explica por qué no debe recomendarse sin nuevos ensayos.'],
 ['La selección de variables puede mejorar parsimonia, pero debe ocurrir dentro del entrenamiento de cada partición. Las variables elegidas pueden ser inestables por correlación. Predicción y interpretación química requieren evaluar estabilidad y plausibilidad, no solo una puntuación de importancia.','Dos longitudes de onda correlacionadas pueden intercambiar importancia entre particiones. Interpreta el patrón conjunto antes de atribuir un mecanismo único.'],
 ['Transferir calibración entre instrumentos o lotes requiere corregir diferencias de respuesta dentro de un alcance evaluado. Muestras de transferencia deben representar variación relevante. Ajustar un sesgo global no garantiza corregir cambios de selectividad o no linealidad.','Un segundo instrumento cambia resolución espectral. Explica por qué una corrección de intercepto podría ser insuficiente.'],
 ['Con clases desbalanceadas, exactitud global puede ocultar fallos de la clase minoritaria. Sensibilidad, especificidad, precisión y curvas dependen del umbral y prevalencia. El coste de errores debe orientar selección y validación del punto de operación.','Si 95 % de muestras son negativas, predecir siempre negativo logra 95 % de exactitud y sensibilidad nula. Evalúa métricas apropiadas.'],
 ['La validación anidada separa ajuste de hiperparámetros y evaluación. Permutaciones prueban asociación bajo una hipótesis y deben respetar grupos o dependencia. Permutar de manera incorrecta puede destruir la estructura necesaria para una comparación válida.','En medidas repetidas, no permutes libremente todas las filas como si fueran sujetos independientes. Define la unidad intercambiable.'],
 ['Interpretabilidad exige relacionar parámetros y variables con el proceso medido. El dominio de aplicación delimita condiciones donde la predicción está respaldada. Explicaciones locales de un modelo no demuestran causalidad ni eliminan correlaciones espurias.','Una muestra con composición fuera de calibración necesita advertencia o rechazo. Propón una comprobación de dominio antes de informar concentración.'],
 ['Un proyecto reproducible define pregunta, partición, pipeline y métricas antes de evaluar prueba. El conjunto independiente no se reutiliza para ajustar decisiones. Reporta incertidumbre, fallos y versiones junto con resultados favorables.','Tras observar mal desempeño en prueba, cambiar el modelo convierte ese conjunto en desarrollo. Explica por qué haría falta una nueva evaluación independiente.']
 ]},
 'cromatografia': {context:'La separación cromatográfica combina distribución entre fases y transporte. Un cromatograma es una representación de señal frente al tiempo, no una lista inequívoca de sustancias: pueden coexistir coelución, discriminación e interferencias. Desarrollar un método exige equilibrar retención, selectividad, eficiencia y tiempo de análisis, además de verificar estabilidad del analito y compatibilidad del detector. La identificación y la cuantificación requieren evidencias y controles adicionales a la separación visual.',reading:[...analytical,['NIST · Datos de retención (inglés)','https://webbook.nist.gov/chemistry/gc-ri/']],lessons:[
 ['El factor de retención relaciona tiempo ajustado y tiempo muerto; la selectividad compara retenciones de dos especies. La resolución incorpora distancia entre picos y anchura. Aumentar retención indefinidamente no mejora eficazmente una separación: modificar selectividad suele ser decisivo.','Calcula k=(tR−tM)/tM para tR=6 min y tM=1 min: k=5. Explica por qué tR aislado no permite comparar columnas distintas.'],
 ['La eficiencia expresa dispersión de bandas mediante platos teóricos o altura equivalente. Difusión longitudinal, múltiples caminos y resistencia a transferencia de masa compiten según velocidad. Más platos pueden mejorar resolución, pero no resuelven necesariamente especies con selectividad prácticamente idéntica.','Interpreta una curva de Van Deemter e identifica por qué velocidades demasiado bajas o altas ensanchan bandas mediante mecanismos distintos.'],
 ['GC separa especies suficientemente volátiles y estables térmicamente. Temperatura, fase estacionaria y flujo condicionan retención; MS añade información de iones y fragmentos. Una biblioteca espectral debe compararse considerando ionización, coelución y evidencia de retención.','Un compuesto termolábil puede degradarse en el inyector. Explica por qué un pico reproducible no garantiza que corresponda intacto al analito original.'],
 ['LC permite analizar especies poco volátiles mediante interacción con fases y composición de eluyente. En LC-MS importan aditivos y caudal compatibles con ionización. Gradientes cambian fuerza de elución; la supresión iónica puede persistir aun cuando el pico parece separado.','Compara un tampón no volátil con un aditivo volátil para LC-MS. Relaciona compatibilidad de fase móvil y respuesta de la fuente.'],
 ['Optimizar separación exige definir el par crítico y ajustar variables controladas. Cambiar fase, pH o temperatura puede alterar selectividad; aumentar longitud afecta presión y duración. Un diseño experimental permite evaluar interacciones que una secuencia de cambios aislados puede pasar por alto.','Plantea dos factores, composición de eluyente y temperatura, y usa resolución del par crítico como respuesta, además de tiempo total.'],
 ['Identificar requiere evidencias ortogonales como retención y espectro comparados con referencias apropiadas. Cuantificar necesita calibración, integración y controles de matriz. El área no es concentración universal: depende de respuesta del detector, recuperación y condiciones de adquisición.','Dos compuestos con áreas iguales pueden tener concentraciones distintas. Explica cómo una calibración específica permite convertir cada señal en cantidad.'],
 ['Extracción líquido-líquido distribuye analito entre fases; SPE utiliza interacción con un sorbente y etapas de carga, lavado y elución. pH y composición regulan retención y selectividad. Recuperación alta y limpieza de matriz son objetivos relacionados, pero pueden competir.','Compara una extracción única con varias de menor volumen total bajo un modelo de partición constante. Indica por qué ese modelo puede fallar si cambia la ionización.'],
 ['Adsorción ocurre en superficies y partición distribuye una especie entre fases. Isotermas lineales facilitan cuantificación; saturación y sitios heterogéneos producen no linealidad y asimetría. La descripción adecuada depende del sistema, no solo del nombre comercial de la columna.','Una carga excesiva puede deformar picos. Relaciona ese efecto con capacidad de fase y explica por qué diluir puede mejorar el comportamiento.'],
 ['Intercambio iónico separa por interacción de cargas con grupos de la fase; fuerza iónica y pH modifican retención. Exclusión por tamaño separa según acceso a poros y volumen hidrodinámico. Interacciones secundarias pueden desviar el mecanismo ideal.','En exclusión ideal, moléculas grandes eluyen antes porque acceden a menos poros. Explica por qué masa molar y tamaño hidrodinámico no son idénticos.'],
 ['Derivatizar modifica propiedades para facilitar separación o detección, pero añade reacciones, posibles subproductos y variabilidad. Debe verificarse rendimiento de derivatización y estabilidad. Un derivado incompleto o múltiple puede dividir señal del mismo compuesto entre varios picos.','Una molécula con varios grupos reactivos puede formar más de un derivado. Propón cómo reconocerías derivatización incompleta con controles.'],
 ['Inyección, columna y detector deben operar dentro de capacidades compatibles. Volumen y solvente de inyección pueden distorsionar bandas; dimensiones y fase determinan selectividad y dispersión. El detector debe registrar suficientes puntos por pico y evitar saturación.','Un volumen de inyección excesivo en un disolvente fuerte puede ensanchar picos en LC. Distingue ese fallo de pérdida de eficiencia de columna.'],
 ['La fase móvil determina competencia por interacciones y transporte. Gradientes deben considerar volumen de demora y reequilibrio; presión depende de viscosidad, caudal y dimensiones. Un mismo programa nominal puede no producir el mismo gradiente efectivo en equipos distintos.','Compara dos instrumentos con diferente volumen de demora. Explica por qué trasladar tiempos de gradiente sin ajustes puede cambiar la separación.'],
 ['Acoplar MS exige controlar entrada de solvente, sales y caudal, además de estabilidad de ionización. Parámetros de fuente modifican aductos y fragmentación. Optimizar únicamente intensidad puede aumentar interferencias o perder información útil para identificación.','Evalúa una condición con señal mayor pero más fragmentación en fuente. Decide qué criterio adicional usarías antes de adoptarla.'],
 ['Los fallos se localizan comparando blancos, patrones y registros previos. Fugas, contaminación, conexiones y desgaste afectan presión, retención o forma de pico de manera diferente. El mantenimiento debe seguir procedimientos del equipo; una modificación sin diagnóstico puede ocultar la causa.','Una subida de presión con retención estable sugiere revisar obstrucciones. Compara esa situación con cambios simultáneos de retención y caudal.'],
 ['La selectividad analítica exige distinguir analito de interferentes, no solo obtener un pico simétrico. La coelución puede ocultarse en una única señal; espectros, iones calificadores o condiciones alternativas ayudan a evaluarla. Separación de patrones puros no garantiza separación de muestras reales.','Un pico con proporción de iones variable a lo largo del tiempo puede contener interferencias. Propón una comprobación con otra selectividad cromatográfica.'],
 ['Los patrones internos corrigen variaciones si acompañan de forma apropiada al analito en las etapas relevantes. La calibración por razones no elimina diferencias de recuperación automáticamente. Añadir el patrón después de extracción no corrige pérdidas ocurridas antes.','Compara un patrón añadido antes de preparar la muestra con otro añadido al vial final. Señala qué fuentes de variabilidad cubre cada diseño.'],
 ['Robustez evalúa pequeñas variaciones deliberadas; transferencia verifica desempeño en otro entorno. Columnas equivalentes nominalmente, volúmenes extracolumna y temperatura efectiva pueden diferir. La aceptación debe basarse en atributos de desempeño y no solo en coincidencia visual.','Diseña cambios pequeños de pH y caudal y evalúa el par crítico. Distingue una prueba de robustez de una recalibración completa.'],
 ['Comparar cromatogramas requiere alinear criterios de integración, unidades y normalización. Área relativa no implica concentración absoluta; cambios de respuesta global pueden alterar proporciones. Evalúa retención, resolución, forma y controles junto con cantidades estimadas.','Dos muestras tienen el mismo porcentaje de área de un pico, pero distinta carga total. Explica por qué no se deduce igual concentración del compuesto.']
 ]},
 'termodinamica': {context:'La termodinámica describe estados y restricciones macroscópicas sin especificar necesariamente un mecanismo molecular. Elegir sistema, variables independientes y convención de trabajo precede a aplicar ecuaciones. Las funciones de estado tienen cambios independientes de la trayectoria, mientras calor y trabajo dependen del proceso. En mezclas reales deben declararse estados estándar y modelos de actividad o fugacidad; las predicciones se contrastan con datos y balances.',reading:[['MIT OCW · Thermodynamics & Kinetics (inglés)','https://ocw.mit.edu/courses/5-60-thermodynamics-kinetics-spring-2008/'],...general],lessons:[
 ['La primera ley conserva energía; la segunda restringe dirección mediante producción de entropía. Con trabajo sobre el sistema positivo, ΔU=q+w. Un proceso reversible es un límite ideal útil para cálculos, no simplemente uno que puede invertirse mediante cualquier procedimiento.','En expansión adiabática q=0, por lo que ΔU=w. Analiza cómo el signo de trabajo determina cambio de energía interna.'],
 ['U, H, A y G corresponden a distintas elecciones de variables naturales. Transformaciones de Legendre permiten reemplazar variables extensivas por sus conjugadas. El potencial apropiado para estabilidad depende de las restricciones: minimizar G requiere temperatura y presión constantes, además de otras condiciones.','Compara criterios de equilibrio a T,V constantes y a T,p constantes. Explica por qué no se intercambian Helmholtz y Gibbs indiscriminadamente.'],
 ['El potencial químico es la contribución molar parcial a Gibbs y determina transferencia de materia. En equilibrio entre fases, cada componente tiene igual potencial químico. Actividad incorpora composición y no idealidad respecto de un estado estándar especificado.','Escribe μ=μ°+RT ln a y explica cómo un gradiente de actividad puede impulsar transferencia aun sin cambiar identidad química.'],
 ['La coexistencia de fases requiere igualdad de temperatura, presión y potenciales químicos de componentes intercambiables. Diagramas y reglas de fases organizan soluciones posibles. Metastabilidad e histéresis recuerdan que alcanzar el estado de menor energía puede requerir superar barreras.','Un líquido sobreenfriado no invalida el equilibrio sólido-líquido: discute el papel de nucleación y la diferencia entre estabilidad y persistencia temporal.'],
 ['El equilibrio de reacción satisface ΔrG=0 y relaciona K con ΔrG°. La composición final surge de este criterio y los balances iniciales. K no depende de las cantidades iniciales a temperatura fija para la misma definición, pero estas sí afectan composición de equilibrio.','Compara dos mezclas iniciales que conducen a distintos cocientes de concentración absolutos, pero al mismo cociente de reacción de equilibrio correctamente definido.'],
 ['Temperatura modifica constantes mediante entalpía de reacción; presión modifica equilibrio según cambios de volumen. Aproximaciones como van ’t Hoff requieren considerar variación de entalpía y posibles cambios de fase. No toda reacción responde igual a comprimir el sistema.','Una reacción gaseosa con igual número de moles a ambos lados puede mostrar poca respuesta ideal a presión. Identifica posibles correcciones por no idealidad.'],
 ['Las derivadas parciales describen respuestas al variar una variable manteniendo otras fijas. Diferenciales exactas caracterizan funciones de estado y permiten relacionar coeficientes. Es esencial señalar las restricciones de la derivada; cambiar qué permanece constante cambia la magnitud física.','Compara (∂U/∂T)V y (∂H/∂T)p. Relaciona ambas con capacidades caloríficas sin asumir igualdad universal.'],
 ['Las ecuaciones de estado aproximan relaciones p,V,T y composición. El gas ideal omite volumen molecular e interacciones; modelos reales incorporan correcciones con límites de validez. Ajustar parámetros no garantiza extrapolación cerca de fases o regiones no estudiadas.','Interpreta Z=pVm/(RT): Z=1 corresponde al modelo ideal, mientras desviaciones reflejan interacciones y volumen excluido bajo condiciones dadas.'],
 ['Calor y trabajo son transferencias de energía, no sustancias almacenadas. La capacidad calorífica depende de restricciones y puede variar con temperatura. En procesos con cambio de fase, aportar calor no necesariamente aumenta temperatura; debe incluirse entalpía de transición.','Calentar a presión constante exige integrar Cp(T). Explica cuándo q≈mcpΔT es razonable y cuándo omite una transición.'],
 ['Integrar datos calorimétricos permite obtener cambios de entalpía y entropía con rutas definidas. Deben incluirse transiciones y condiciones de referencia. Corregir línea base y calibración es parte del modelo experimental, y la incertidumbre de datos afecta integrales y predicciones.','Para Cp aproximadamente constante, ΔS=Cp ln(T₂/T₁) en una etapa reversible. Indica por qué temperatura debe expresarse en kelvin.'],
 ['Las relaciones de Maxwell resultan de igualdad de derivadas cruzadas de potenciales suficientemente regulares. Conectan magnitudes difíciles de medir con respuestas accesibles. Aplicarlas requiere identificar el potencial y sus variables naturales; signos incorrectos suelen provenir de esa elección.','Desde dG=−S dT+V dp, deriva (∂S/∂p)T=−(∂V/∂T)p e interpreta qué propiedades relaciona.'],
 ['Gibbs-Duhem expresa que los potenciales químicos de una mezcla no varían independientemente. A temperatura y presión constantes, la suma de ni dμi es cero. Sirve para comprobar consistencia de modelos de mezcla y relacionar respuestas de componentes.','En una mezcla binaria, conocer una variación de potencial químico restringe la del otro. Explica por qué no pueden ajustarse coeficientes sin consistencia mutua.'],
 ['Fugacidad reemplaza presión en expresiones de potencial químico de gases reales; actividad cumple un papel análogo con estados estándar de mezclas. Sus coeficientes dependen del modelo y condiciones. Usar valores de otra temperatura o convención puede introducir errores sistemáticos.','Compara f=φp con p en un gas no ideal. Señala qué límite recupera comportamiento ideal y qué datos permiten estimar φ.'],
 ['Las propiedades de exceso cuantifican diferencia respecto de una mezcla ideal bajo la misma definición. Modelos de Gibbs de exceso describen interacciones y permiten calcular coeficientes de actividad. Parámetros ajustados requieren datos representativos y evaluación de consistencia termodinámica.','Una mezcla con entalpía de exceso positiva no permite por sí sola predecir miscibilidad: también debe considerarse la contribución entrópica a Gibbs.'],
 ['Clapeyron relaciona pendiente de coexistencia con entropía y volumen de transición. Clausius-Clapeyron introduce aproximaciones útiles para vapor y líquido, como comportamiento gaseoso ideal y volumen líquido pequeño. Integrar suponiendo entalpía constante limita el intervalo de temperatura.','Explica por qué graficar ln p frente a 1/T puede estimar entalpía de vaporización, y qué indica una curvatura sistemática.'],
 ['El equilibrio electroquímico incorpora energía eléctrica al potencial químico. Diferencias de potencial, actividades y transporte de carga se acoplan. Las celdas reales pueden presentar sobrepotenciales y caída óhmica; una tensión bajo corriente no equivale al potencial reversible.','Compara voltaje en circuito abierto con voltaje durante descarga. Identifica contribuciones cinéticas y resistivas que la ecuación de Nernst sola no describe.'],
 ['La función de partición suma pesos estadísticos de estados y conecta niveles microscópicos con propiedades termodinámicas. Aproximaciones de independencia permiten separar contribuciones traslacionales, rotacionales y vibracionales. Deben considerarse indistinguibilidad, degeneración y validez de modelos moleculares.','Al bajar temperatura, estados excitados poco poblados contribuyen menos. Relaciona separación energética con el factor de Boltzmann.'],
 ['Resolver un equilibrio implica declarar componentes, fases, balances y modelo de potenciales. Las soluciones matemáticas deben cumplir positividad y estabilidad. Contrastar datos independientes permite distinguir error numérico de insuficiencia del modelo o parámetros incorrectos.','Una solución calculada con concentración negativa es inadmisible aunque el algoritmo converja. Propón restricciones y comprobaciones de balances para detectarla.']
 ]},
 'cinetica-catalisis': {context:'La cinética infiere velocidades y mecanismos a partir de evolución temporal. Un mecanismo debe explicar dependencia con concentración, temperatura y condiciones, pero los datos pueden admitir varios modelos. La catálisis modifica rutas y velocidades sin cambiar el equilibrio termodinámico global. Conviene separar reacción intrínseca, transporte, respuesta instrumental y desactivación, pues cualquiera puede controlar la señal observada.',reading:[['MIT OCW · Thermodynamics & Kinetics (inglés)','https://ocw.mit.edu/courses/5-60-thermodynamics-kinetics-spring-2008/'],...analytical],lessons:[
 ['Las leyes integradas relacionan concentración y tiempo para modelos y condiciones concretas. Un ajuste debe respetar condiciones iniciales y estructura de error. Linealidad en una gráfica transformada es evidencia limitada: compara modelos en la escala original y examina residuos.','Para primer orden, t½=ln 2/k no depende de concentración inicial. Contrasta con segundo orden e identifica una prueba experimental.'],
 ['Arrhenius relaciona k con temperatura mediante una energía de activación aparente. Esa energía puede cambiar si cambia mecanismo o régimen de transporte. Un ajuste lineal de ln k frente a 1/T debe incluir unidades coherentes y un intervalo físicamente comparable.','Una curvatura en la gráfica de Arrhenius puede indicar cambio de mecanismo o condiciones. Explica por qué no conviene forzar una única recta.'],
 ['Estado estacionario aproxima derivada casi nula de un intermediario; preequilibrio supone una etapa reversible rápida cercana al equilibrio. Son hipótesis diferentes y deben justificarse por escalas temporales. Aplicarlas incorrectamente puede producir una ley aparentemente plausible pero incompatible con datos.','En A→I→P, un intermediario de vida corta puede no acumularse. Distingue esa situación de una primera etapa A⇌I realmente equilibrada.'],
 ['Reacciones consecutivas generan y consumen intermediarios; las paralelas compiten por un reactivo. La selectividad puede variar con tiempo y temperatura. Maximizar conversión no siempre maximiza rendimiento del producto intermedio deseado.','Para A→B→C, B puede alcanzar un máximo y luego disminuir. Explica cómo elegirías un tiempo de observación si B es el objetivo.'],
 ['En catálisis homogénea reactivos y catalizador comparten fase; en heterogénea intervienen superficies e interfaces. Adsorción, transporte y número de sitios accesibles condicionan velocidades aparentes. Comparar actividad exige normalización y control de limitaciones externas.','Dos sólidos con igual masa pueden tener distinto número de sitios activos. Explica por qué velocidad por gramo no equivale a actividad intrínseca por sitio.'],
 ['Michaelis-Menten aproxima velocidades iniciales bajo supuestos específicos de mecanismo y concentración. Km no es universalmente una constante de disociación; Vmax depende de enzima activa. Inhibición, cooperatividad y agotamiento de sustrato requieren modelos adicionales.','Para v=Vmax[S]/(Km+[S]), a [S]=Km se obtiene Vmax/2. Explica qué supuestos necesitas antes de usar esta igualdad experimentalmente.'],
 ['El método diferencial estima velocidades desde derivadas y puede amplificar ruido; el integral ajusta evolución temporal de un modelo. Ambos requieren relación válida entre señal y concentración. Seleccionar el método depende de resolución temporal y error de medición.','Compara derivar una curva ruidosa y ajustar su forma integrada. Explica por qué suavizar excesivamente puede sesgar una velocidad inicial.'],
 ['Las técnicas rápidas deben resolver tiempos menores que los procesos de interés. Tiempo muerto, mezcla y respuesta del detector pueden ocultar etapas iniciales. La señal medida es una combinación de dinámica química e instrumental y puede requerir caracterización independiente.','Si una reacción termina antes de que la mezcla sea homogénea, la curva observada no informa directamente su constante intrínseca.'],
 ['La estimación de parámetros exige datos que los identifiquen. Correlaciones fuertes entre parámetros producen incertidumbre grande aunque el ajuste visual sea bueno. Variar condiciones iniciales y diseñar tiempos de observación puede aportar más información que aumentar puntos redundantes.','Dos combinaciones de parámetros reproducen la misma curva. Propón una segunda condición inicial para separarlas y evaluar identificabilidad.'],
 ['Los residuos deben evaluarse en función de tiempo y predicción. Estructura sistemática puede indicar mecanismo incompleto o error no modelado. Comparar modelos requiere penalizar complejidad y considerar plausibilidad; el menor error de entrenamiento no garantiza mejor explicación.','Un modelo con muchos parámetros sigue cada fluctuación. Contrástalo con datos independientes antes de interpretarlo como mecanismo químico.'],
 ['La teoría de colisiones relaciona frecuencia de encuentros y probabilidad de reacción. Energía suficiente y orientación importan, pero en disolución intervienen jaula y difusión. No toda colisión produce reacción y la concentración no determina por sí sola la fracción eficaz.','Compara choques geométricamente posibles con choques que conducen a producto. Explica cómo una barrera reduce la fracción reactiva.'],
 ['La teoría del estado de transición relaciona velocidad y energía libre de activación bajo un modelo de superficie energética. El estado de transición no es un intermediario aislable. Entalpía y entropía de activación describen contribuciones y dependen del marco experimental.','En un perfil de energía, distingue máximos de transición y mínimos de intermediarios. Explica por qué ambos tienen papeles cinéticos diferentes.'],
 ['En solución, difusión y reorganización del entorno pueden limitar encuentros o conversión. La viscosidad, fuerza iónica y solvatación afectan velocidades. Una ley aparente puede mezclar control por difusión y control químico, especialmente en reacciones muy rápidas.','Si cambiar viscosidad altera velocidad, discute una contribución de difusión sin concluir automáticamente que sea el único mecanismo limitante.'],
 ['La fotoquímica inicia procesos mediante absorción de luz; en cadenas, especies reactivas se regeneran durante propagación y se consumen en terminación. Intensidad absorbida y rendimiento cuántico deben distinguirse. Cambios de iluminación pueden alterar velocidades de forma no lineal.','Una molécula absorbente no garantiza un producto por fotón. Define rendimiento cuántico y señala reacciones competitivas que lo modifican.'],
 ['Las isotermas relacionan cobertura y presión o concentración en equilibrio. Langmuir supone sitios equivalentes y adsorción sin interacciones laterales en su forma básica. Heterogeneidad y multicapa requieren otros modelos; un buen ajuste no demuestra literalmente cada supuesto.','Para θ=KP/(1+KP), identifica límites de baja presión y saturación. Explica cómo cambia sensibilidad de cobertura a presión.'],
 ['Langmuir-Hinshelwood describe reacciones entre especies adsorbidas dentro de un modelo superficial. Competencia por sitios puede producir inhibición al aumentar un reactivo. La ley resultante depende de adsorción, etapa limitante y balance de sitios.','A alta presión de una especie, bloquear sitios puede reducir velocidad. Distingue este efecto de agotamiento del otro reactivo.'],
 ['La transferencia de masa puede controlar suministro a una superficie o difusión dentro de poros. Velocidades observadas bajo estas limitaciones no reflejan solo constantes químicas. Variar agitación, tamaño de partícula o geometría ayuda a evaluar el régimen.','Si reducir tamaño de partícula aumenta velocidad específica, investiga difusión interna antes de atribuir el cambio a una nueva química superficial.'],
 ['Selectividad y actividad pueden cambiar por envenenamiento, depósitos, sinterización o transformación de especies activas. El diseño del ensayo debe registrar tiempo de operación y controles. Comparar catalizadores recién preparados y envejecidos sin esa información puede ser engañoso.','Una conversión decreciente puede reflejar desactivación o variación de alimentación. Propón controles para distinguir ambas explicaciones.']
 ]},
 'organica-avanzada': {context:'La estructura orgánica condiciona distribución electrónica, geometría y accesibilidad de los centros reactivos. Un mecanismo representa redistribución de electrones y debe conservar átomos y carga; las flechas parten de pares electrónicos o enlaces. La propuesta se contrasta con cinética, estereoquímica y productos, no solamente con una ecuación global. En síntesis, selectividad, aislamiento y compatibilidad entre etapas importan tanto como reconocer una transformación individual.',reading:[['OpenStax · Organic Chemistry (inglés)','https://openstax.org/books/organic-chemistry/pages/1-why-this-chapter']],lessons:[
 ['Los efectos inductivos se transmiten mediante enlaces y los de resonancia requieren orbitales compatibles. El impedimento estérico modifica acceso y conformación. Acidez, estabilidad y velocidad son magnitudes relacionadas pero distintas: un sustituyente puede favorecer un equilibrio y dificultar el ataque de un reactivo.','Compara estabilización de un carbocatión alílico con la de uno sin conjugación. Dibuja contribuyentes de resonancia sin mover núcleos.'],
 ['El control cinético favorece el producto formado por la barrera menor; el termodinámico favorece el más estable si existe reversibilidad y tiempo para equilibrar. Temperatura no determina por sí sola el régimen. Deben conocerse las interconversiones y condiciones de reacción.','En un diagrama energético, dibuja dos barreras y dos productos de distinta energía. Identifica qué información necesitas para predecir la proporción observada.'],
 ['La estereoselectividad expresa preferencia entre productos estereoisoméricos; la estereoespecificidad relaciona estereoquímica del reactivo con la del producto por el mecanismo. La razón enantiomérica o diastereomérica debe medirse, no deducirse solo de una representación plana.','Una mezcla 90:10 de enantiómeros tiene exceso enantiomérico de 80 %. Explica la diferencia entre esta medida y rendimiento químico.'],
 ['La quimioselectividad permite transformar una función entre varias reactivas. Proteger temporalmente un grupo puede ayudar, pero añade pasos y pérdidas y requiere condiciones compatibles de retirada. La mejor estrategia considera también transformaciones directas y orden de etapas.','Compara una ruta que protege un alcohol con otra que emplea un reactivo selectivo. Cuenta etapas, rendimiento acumulado y posibles incompatibilidades.'],
 ['La retrosíntesis analiza el objetivo hacia precursores mediante desconexiones justificadas. Los sintones son idealizaciones; deben traducirse a equivalentes sintéticos accesibles. Una desconexión útil reduce complejidad sin ignorar regioquímica, estereoquímica ni disponibilidad de materiales.','Desconecta un enlace C–C adyacente a un carbonilo y propone papeles nucleófilo/electrófilo. Comprueba que la reacción directa pueda producir el objetivo.'],
 ['Una ruta se evalúa por selectividad, rendimiento global, seguridad, operaciones y residuos. El rendimiento acumulado multiplica rendimientos de etapas consecutivas; una etapa muy exigente puede dominar la viabilidad. La economía atómica no incluye por sí sola disolventes o purificación.','Cinco etapas consecutivas al 80 % dan aproximadamente 33 % global. Compara con tres etapas al 75 % y discute limitaciones de usar solo este indicador.'],
 ['La conformación cambia por rotación sin romper enlaces; la configuración requiere distinguir arreglos estables según conectividad y estereoquímica. Las reglas CIP permiten asignar R/S, pero esa etiqueta no determina el signo de rotación óptica. La simetría global puede eliminar quiralidad.','Un compuesto con centros estereogénicos puede ser meso. Examina planos internos de simetría antes de predecir actividad óptica.'],
 ['La aromaticidad exige un sistema cíclico conjugado con condiciones geométricas y electrónicas adecuadas. La regla 4n+2 describe casos de Hückel, no cualquier anillo. En heterociclos, algunos pares libres participan en el sistema π y otros conservan un papel localizado.','Compara piridina y pirrol: identifica el orbital del par libre del nitrógeno y relaciona su participación con basicidad y aromaticidad.'],
 ['IR identifica patrones vibracionales y MS aporta masa y fragmentación; sus evidencias son complementarias. Una banda o fragmento no suele demostrar una estructura única. Deben explicarse fórmula, insaturaciones, grupos funcionales y fragmentos con un mismo modelo químico.','Una banda carbonilo y una fórmula compatible no distinguen por sí solas todos los isómeros. Propón una medición adicional que descarte alternativas.'],
 ['RMN 1D informa desplazamientos, integraciones y acoplamientos. Correlaciones 2D conectan núcleos según el experimento: COSY, HSQC y HMBC responden preguntas diferentes. Solapamiento, intercambio y relajación afectan interpretación; no toda ausencia de correlación demuestra ausencia de conexión.','Usa una correlación HSQC para asociar protón y carbono directamente enlazados; reserva una correlación HMBC para explorar conexiones de mayor alcance.'],
 ['Enoles y enolatos permiten reactividad en carbono α. La distribución depende de acidez, base, disolvente y posibilidad de equilibrio. Enolatos cinéticos y termodinámicos pueden diferir; también importa la selectividad O/C y la geometría del nucleófilo.','Una cetona asimétrica ofrece posiciones α no equivalentes. Dibuja ambos enolatos y separa argumentos de velocidad de formación y estabilidad relativa.'],
 ['Construir enlaces C–C requiere emparejar centros con reactividad compatible y controlar funciones competidoras. Adiciones a carbonilo, condensaciones y acoplamientos conservan patrones distintos de oxidación y conectividad. Planear el trabajo exige seguimiento de cada carbono del producto.','En una adición de un nucleófilo carbonado a un aldehído, señala el nuevo enlace y el origen del oxígeno del alcohol resultante.'],
 ['Los acoplamientos metálicos conectan fragmentos mediante ciclos que pueden incluir adición oxidante, transmetalación y eliminación reductora. Ligandos, bases y sustratos modifican velocidad y selectividad. El nombre de una reacción no prueba el mecanismo de todas sus variantes.','Representa un ciclo conceptual de acoplamiento y verifica conservación del metal. Identifica qué etapa cambiaría al modificar el socio organometálico.'],
 ['Las reacciones pericíclicas reorganizan enlaces mediante estados de transición cíclicos y relaciones de simetría orbital. Condiciones térmicas o fotoquímicas pueden conducir a reglas diferentes. La conservación de simetría se aplica a un mecanismo concertado, no a cualquier transformación con el mismo producto.','En una cicloadición de Diels–Alder, sigue la conectividad y estereoquímica de diene y dienófilo. Explica el papel de la conformación s-cis.'],
 ['Oxidación y reducción orgánicas cambian estados formales y enlaces a heteroátomos o hidrógeno. La selección de reactivo depende del grupo objetivo y de funciones susceptibles. Una secuencia útil evita sobreoxidación o reducción de grupos necesarios y considera residuos y operaciones.','Compara convertir un alcohol primario en aldehído o en ácido. Identifica qué control de transformación es necesario sin asumir que ambos productos se obtienen indistintamente.'],
 ['La síntesis de heterociclos combina formación de enlaces y cierre de anillo. Tamaño, tensión, aromaticidad y posición de heteroátomos influyen en viabilidad y regioselectividad. El cierre intramolecular compite con procesos intermoleculares según concentración y reactividad de los extremos.','Propón una desconexión de un anillo con nitrógeno y comprueba que los precursores contienen los átomos y funciones apropiados para cerrar el ciclo.'],
 ['La economía atómica compara masa del producto deseado con la masa estequiométrica de reactivos. Es distinta de rendimiento y factor E. Un diseño responsable considera peligros, energía, disolventes y recuperación, además de balances químicos; una cifra favorable no garantiza seguridad global.','Una reacción de adición puede tener buena economía atómica y consumir mucho disolvente. Explica qué indicador adicional usarías para evaluar residuos reales.'],
 ['Comparar rutas multietapa exige una base común: misma escala, pureza y producto. Documenta selectividad, aislamiento, disponibilidad, riesgos y reproducibilidad, además de rendimientos. Las ventajas de una ruta convergente dependen de la etapa de unión y de la complejidad de ambos fragmentos.','Construye una tabla entre dos rutas con igual producto: etapas lineales, rendimiento acumulado, purificaciones y residuos. Justifica qué criterio pesa más según la aplicación.']
 ]},
 'analitica-cuantitativa': {context:'Una medición analítica comienza por definir analito, matriz y decisión que se tomará. Muestreo, preparación, calibración y cálculo forman una cadena: aumentar precisión instrumental no corrige una muestra no representativa. La calidad se demuestra mediante controles y estimaciones de incertidumbre. Siempre distingue concentración total y especie libre, resultado observado y valor de referencia, e intervalo validado y extrapolación.',reading:[...analytical,...statistics],lessons:[
 ['El muestreo debe representar la población espacial o temporal de interés. La preparación puede introducir contaminación, pérdidas o transformaciones del analito. Réplicas de campo, extracción y lectura estiman variabilidades diferentes; repetir inyecciones no equivale a aumentar el número de muestras independientes.','Diseña una muestra compuesta de un tanque heterogéneo. Explica qué información se pierde al mezclar y cuándo conviene analizar puntos separados.'],
 ['La trazabilidad relaciona un resultado con referencias mediante una cadena documentada de calibraciones con incertidumbre. El presupuesto debe incluir etapas relevantes y sus correlaciones. No confunde trazabilidad documental con adecuación del método: una medida trazable puede tener incertidumbre excesiva para la decisión.','Una concentración calculada desde masa y volumen depende de balanza, pureza y material volumétrico. Enumera esas contribuciones antes de redondear el resultado.'],
 ['La gravimetría convierte analito en una forma pesable de composición conocida. Precipitación, digestión, filtración y secado pueden introducir coprecipitación o pérdidas. El factor gravimétrico transforma masa de producto en analito solo si identidad y estequiometría están justificadas.','Si se pesa AgCl, relaciona sus moles con los de cloruro mediante proporción 1:1. Evalúa cómo afecta un precipitado húmedo al resultado.'],
 ['La volumetría utiliza cantidad de titulante y estequiometría para inferir analito. Requiere concentración conocida y reacción suficientemente definida. La curva permite seleccionar detección del punto final y reconocer regiones tampón o saltos pequeños; equivalencia química y señal observada no son idénticas.','Una valoración 1:1 con 20,00 mL de titulante 0,1000 M consume 2,000 mmol. Indica qué blanco o corrección podría cambiar la estimación.'],
 ['Calibrar establece una relación entre señal y cantidad bajo condiciones definidas. Un material de referencia puede ayudar a evaluar sesgo, pero debe ser adecuado a matriz y mensurando. Linealidad aparente no demuestra ausencia de errores; revisa residuos y el intervalo de trabajo.','Un patrón acuoso y una muestra salina pueden dar pendientes diferentes. Explica por qué una curva excelente en agua no valida automáticamente la cuantificación en esa matriz.'],
 ['Validar demuestra que un procedimiento es apto para su finalidad. Selectividad, precisión, sesgo, rango, robustez y límites se evalúan en condiciones relevantes. No existe un conjunto universal de umbrales para todas las matrices; los criterios de aceptación deben vincularse a la decisión prevista.','Distingue validar un método para trazas en agua potable de otro para una materia prima concentrada. Identifica qué exigencias cambian y por qué.'],
 ['Los balances reúnen todas las especies de un componente y la suma de cargas. Junto con constantes, evitan resultados incompatibles con conservación. Una aproximación que elimina una especie debe contrastarse posteriormente, especialmente cerca de equivalencia o en sistemas muy diluidos.','Plantea balance total de un metal que forma ML y ML₂; no reemplaces su concentración total por la del ion libre sin justificarlo.'],
 ['Las titulaciones ácido-base requieren considerar fuerza de ácidos y bases, dilución y equilibrios secundarios. El tramo cercano a equivalencia determina sensibilidad del punto final. Para mezclas y ácidos polipróticos, constantes próximas pueden impedir separar claramente consumos estequiométricos.','Explica por qué un ácido diprótico no siempre presenta dos saltos resolubles aunque consuma dos equivalentes de base.'],
 ['Una titulación redox se basa en transferencia de electrones; una complejométrica, en formación de complejos. pH, ligandos y reacciones secundarias afectan constantes condicionales. La estequiometría debe corresponder al medio real, incluyendo estados de oxidación y especies predominantes.','En una titulación con EDTA, discute por qué controlar pH cambia fracción de ligando disponible y selectividad entre metales.'],
 ['Las valoraciones de precipitación dependen de solubilidad, concentraciones y posibles coprecipitaciones. El punto final puede detectarse electroquímicamente o por indicadores apropiados. Un precipitado visible no establece equivalencia; debe relacionarse la señal con el exceso de especie titulante o analito.','Traza cualitativamente concentración de Ag⁺ al titular cloruro. Diferencia la región controlada por solubilidad del exceso posterior de plata.'],
 ['Una distribución describe variabilidad; un intervalo de confianza evalúa un procedimiento de estimación bajo supuestos. Aumentar réplicas puede estrechar el intervalo del promedio, sin eliminar sesgo. Para muestras pequeñas y varianza desconocida suele intervenir la distribución t bajo normalidad aproximada.','Compara dispersión de mediciones con incertidumbre del promedio. Explica por qué dividir por √n no corrige un error de calibración.'],
 ['Un contraste compara datos con una hipótesis bajo un modelo probabilístico. Error tipo I y tipo II representan decisiones distintas; significación estadística no mide magnitud ni relevancia práctica. Deben reportarse efecto e incertidumbre y considerar multiplicidad si se realizan numerosos contrastes.','Una diferencia muy pequeña puede ser significativa con muchas muestras. Decide si cumple una tolerancia analítica, en lugar de basarte únicamente en p<0,05.'],
 ['La regresión estima relaciones entre variables y debe concordar con la estructura de error. Residuos muestran curvatura, heterocedasticidad y puntos influyentes. Un R² alto puede coexistir con sesgo sistemático; ponderar exige justificar pesos, no usarlos solo para mejorar una cifra.','Una calibración con residuos crecientes puede requerir ponderación. Compara predicciones en el extremo bajo, donde un ajuste global puede fallar.'],
 ['Propagar incertidumbre requiere sensibilidades del modelo y covarianzas cuando entradas no son independientes. La suma cuadrática es una aproximación útil bajo condiciones específicas. Modelos no lineales o distribuciones asimétricas pueden requerir simulación y evaluación de intervalos no simétricos.','Para c=m/V con entradas independientes, combina incertidumbres relativas. Explica por qué compartir una misma calibración puede correlacionar varios resultados.'],
 ['Seleccionar método implica analizar forma química, matriz, intervalo y objetivo. Digestión y extracción no garantizan recuperar todas las especies por igual. El método debe distinguir analito de interferentes y entregar incertidumbre adecuada, no simplemente el menor límite instrumental disponible.','Compara medir metal total después de digestión con medir una especie concreta. Define cuál responde a la pregunta antes de elegir el equipo.'],
 ['Blancos de reactivos, proceso y campo detectan contaminaciones en etapas diferentes. Controles positivos, fortificaciones y referencias evalúan otros fallos. El plan debe especificar frecuencia y acciones frente a resultados fuera de criterio, evitando correcciones improvisadas tras observar datos.','Un blanco instrumental limpio y un blanco de extracción contaminado localizan un problema anterior a la inyección. Describe qué revisarías primero.'],
 ['Recuperación estima el comportamiento de una adición conocida y no siempre reproduce el analito nativo. Precisión describe dispersión; sesgo, diferencia respecto de referencia. Fortificar antes o después de extracción permite separar parcialmente pérdidas y efectos de matriz, según el diseño.','Una recuperación del 100 % con señal suprimida puede resultar de compensaciones. Propón controles que distingan extracción, calibración y respuesta instrumental.'],
 ['El informe de validación debe enlazar finalidad, protocolo, evidencia y límites. Incluye matrices, niveles, réplicas, criterios y desviaciones, además de resultados. Una conclusión responsable restringe el uso a lo estudiado y señala qué cambios exigen verificación o revalidación.','Si se validó en agua superficial, explica por qué aplicar directamente a sedimento exige evaluar extracción, interferencias e incertidumbre adicionales.']
 ]},
 'instrumental': {context:'Un instrumento transforma una interacción física o química en señal medible. La señal depende de analito, matriz, condiciones de adquisición y procesamiento. Sensibilidad, selectividad y resolución representan capacidades diferentes; ninguna técnica responde a todas las preguntas. Una interpretación sólida conecta principio de funcionamiento, calibración, controles y límites, y distingue detección de una señal de identificación inequívoca de una sustancia.',reading:analytical,lessons:[
 ['UV-visible mide absorción electrónica; fluorescencia mide emisión tras excitación y depende también de rendimiento cuántico y apagamiento. Beer-Lambert requiere condiciones apropiadas y ausencia de contribuciones no modeladas. Dispersión, luz parásita y reabsorción pueden introducir desviaciones.','Una curva de absorbancia lineal a bajas concentraciones puede curvarse al aumentar concentración. Distingue un efecto instrumental de un equilibrio químico del analito.'],
 ['La espectrometría atómica requiere generar especies que absorban o emitan radiación característica. Atomización y excitación son procesos distintos. Interferencias químicas, espectrales e ionización afectan señal y pueden requerir corrección de fondo, modificación de matriz o selección de otra línea.','Dos elementos con líneas próximas pueden interferir en emisión. Explica por qué aumentar resolución espectral no corrige necesariamente una atomización incompleta.'],
 ['Una fuente produce iones y un analizador los separa según relaciones dinámicas asociadas a m/z. Ionización dura o suave modifica fragmentación y especies observadas. Resolución, exactitud de masa y sensibilidad no son sinónimos; especifica polaridad, carga y tipo de ion al interpretar datos.','Un pico [M+H]⁺ no tiene la misma masa que M neutra. Comprueba carga y aducto antes de asignar una fórmula elemental.'],
 ['Los fragmentos reflejan estructuras, energías y vías de disociación dependientes de la técnica. Una coincidencia espectral aporta evidencia pero puede ser ambigua entre isómeros. Relaciona precursor, pérdidas neutras y fragmentos con conservación elemental y condiciones de adquisición.','Una pérdida de 18 Da puede ser compatible con agua, pero no identifica por sí sola una estructura. Busca evidencia complementaria y condiciones de fragmentación.'],
 ['La matriz puede alterar extracción, transporte, atomización o ionización. Preparación selectiva, dilución y patrones internos pueden reducir efectos, aunque no los eliminan automáticamente. La comparación de calibraciones y fortificaciones debe distinguir pérdidas de preparación y cambios de respuesta.','Compara una fortificación antes y otra después de extracción. Explica qué cocientes permiten estudiar recuperación y cuáles reflejan respuesta de matriz.'],
 ['El aseguramiento de calidad verifica desempeño durante la secuencia mediante blancos, referencias y controles. Validación inicial y control rutinario se complementan. Definir criterios antes de medir permite detectar deriva, contaminación y fallos sin seleccionar retrospectivamente solo los resultados favorables.','Inserta controles distribuidos en una corrida y representa respuesta frente al tiempo. Distingue deriva gradual de un salto después de mantenimiento.'],
 ['Señal y ruido dependen de fuente, detector y procesamiento. Promediar ruido aleatorio independiente puede mejorar señal-ruido aproximadamente con √n, pero no elimina deriva ni sesgo. Filtrar demasiado puede deformar picos y perder información temporal.','Cuatro lecturas independientes promediadas podrían duplicar señal-ruido idealmente. Explica por qué no se cumple si domina una fluctuación lenta compartida.'],
 ['Fuentes, selectores de longitud de onda, óptica y detectores determinan la respuesta espectral. El ancho de banda afecta resolución y flujo de fotones; una ganancia mayor no crea información ilimitada. Linealidad, corriente oscura y saturación deben caracterizarse.','Reducir una rendija puede mejorar resolución y disminuir intensidad. Describe el compromiso experimental antes de decidir la configuración.'],
 ['Sensibilidad de calibración se relaciona con pendiente, mientras rango dinámico describe el intervalo utilizable. Un detector puede saturarse y una respuesta pequeña puede seguir siendo precisa si el ruido es bajo. No compares técnicas solo por pendientes con unidades diferentes.','Una curva pierde proporcionalidad en el extremo alto. Define cómo identificarías el límite de cuantificación superior y evitarías extrapolar.'],
 ['La adquisición discretiza señales en tiempo o frecuencia y el procesamiento modifica datos. Muestreo insuficiente pierde detalle; suavizado, corrección de línea base e integración requieren parámetros documentados. Conserva datos originales para evaluar si una conclusión depende del tratamiento.','Un pico con muy pocos puntos puede dar área inestable. Relaciona frecuencia de adquisición, ancho del pico y precisión de integración.'],
 ['IR observa vibraciones con cambio de momento dipolar; Raman requiere cambio de polarizabilidad. Las técnicas ofrecen información complementaria y distinta sensibilidad a agua y fluorescencia. Posición, intensidad y ancho de bandas dependen del entorno, no solo de una etiqueta de grupo funcional.','Una vibración simétrica puede ser débil en IR y intensa en Raman. Explica por qué combinar espectros ayuda a asignar estructura.'],
 ['RMN estudia núcleos con espín en un campo magnético. Desplazamientos, acoplamientos e intensidades informan entorno y conectividad, pero integración cuantitativa exige controlar relajación y adquisición. Mayor campo mejora ciertas separaciones sin eliminar todos los solapamientos.','Dos protones químicamente distintos pueden solaparse accidentalmente. Propón un experimento adicional en lugar de concluir que son equivalentes.'],
 ['Potenciometría mide potencial con corriente despreciable; voltametría estudia corriente al variar potencial. Electrodo de referencia, transporte y superficie condicionan interpretación. Un pico voltamétrico no depende exclusivamente de concentración: cinética, difusión y adsorción también intervienen.','Compara una medida de pH potenciométrica con un barrido redox. Identifica qué variable se controla y cuál se registra en cada caso.'],
 ['Las técnicas térmicas detectan cambios de masa o flujo de calor; las superficiales examinan regiones con profundidades de información específicas. Un evento térmico puede corresponder a pérdida de solvente, transición o descomposición. Composición superficial no equivale necesariamente a composición global.','Una pérdida de masa al calentar no identifica por sí sola el gas liberado. Propón acoplar otra técnica o analizar productos para sostener la asignación.'],
 ['Las interferencias espectrales superponen señales; las químicas modifican generación o estabilidad de especies medidas. Correcciones requieren supuestos que pueden fallar. Combina separación, selección de señal y controles de matriz para verificar que la respuesta corresponde al analito.','Cambiar una longitud de onda puede resolver solapamiento, pero no una reacción que consume analito antes de medir. Diseña controles para diferenciar ambos casos.'],
 ['Los límites dependen de variabilidad del blanco o de señales bajas, modelo de calibración y probabilidades de error. LOD no garantiza cuantificación fiable y LOQ exige un criterio de calidad. Valores instrumentales no sustituyen límites del procedimiento completo.','Compara el ruido de una solución limpia con el de un extracto real. Explica por qué el límite del método puede ser peor que el declarado para el detector.'],
 ['Seleccionar instrumentación exige ponderar analitos, matriz, resolución, productividad, mantenimiento y coste total. Una plataforma más sensible puede exigir preparación compleja o mayor experiencia. Los criterios deben explicitarse y relacionarse con la decisión analítica, no con prestigio del equipo.','Compara dos técnicas para un mismo intervalo de concentración e incluye consumibles, capacidad de confirmación e incertidumbre en la evaluación.'],
 ['Un informe crítico describe principio, desempeño y evidencia de aptitud, además de limitaciones. Debe distinguir especificaciones del fabricante y resultados obtenidos en la matriz estudiada. Incluye condiciones, controles, calibración y causas plausibles de discrepancia.','Revisa un método que informa solo R². Identifica qué falta para evaluar selectividad, sesgo, precisión y utilidad fuera del conjunto de calibración.']
 ]},
 'general-i': {context:'La química general conecta tres representaciones: lo observable, el modelo de partículas y el lenguaje de fórmulas y ecuaciones. Una explicación completa debe relacionarlas: una medición macroscópica no muestra directamente un orbital ni una molécula. Al resolver problemas, define el sistema y las unidades, establece qué se conserva y comprueba si el resultado tiene una magnitud razonable. Los modelos tienen supuestos; identificar cuándo dejan de ser adecuados es parte del aprendizaje.',reading:general,lessons:[
 ['Los orbitales representan estados electrónicos y distribuciones de probabilidad, no trayectorias planetarias. Los números cuánticos describen energía, forma, orientación y espín dentro del modelo. En átomos multielectrónicos, apantallamiento y repulsiones modifican las energías; Aufbau, Pauli y Hund orientan las configuraciones, con excepciones que deben contrastarse experimentalmente.','En N, 1s²2s²2p³, los tres electrones p ocupan orbitales distintos antes de aparearse. Dibuja las casillas y explica por qué esto no significa tres órbitas circulares.'],
 ['Las tendencias periódicas resultan del equilibrio entre carga nuclear, apantallamiento y distancia radial. A lo largo de un período suele aumentar la atracción efectiva sobre electrones de valencia; al bajar en un grupo aparecen capas más extensas. Radio, ionización y afinidad electrónica no varían con reglas idénticas y presentan excepciones por subcapas y apareamiento.','Compara Na y Mg: el aumento de atracción efectiva ayuda a explicar sus radios. Después compara Mg y Al para discutir por qué la primera energía de ionización no aumenta uniformemente.'],
 ['Lewis organiza electrones y cargas formales; VSEPR predice geometrías aproximadas por repulsión entre regiones electrónicas. La geometría electrónica incluye pares libres, mientras la molecular describe posiciones atómicas. Polaridad molecular depende de la suma vectorial de dipolos y de la simetría; un enlace polar no garantiza una molécula polar.','CO₂ es lineal y sus dipolos se compensan; H₂O es angular y conserva un dipolo neto. Identifica pares libres y distingue geometría de distribución electrónica.'],
 ['Dispersión, interacciones dipolares y puentes de hidrógeno contribuyen a la cohesión de líquidos y sólidos moleculares. Su efecto depende también del tamaño, la polarizabilidad y la superficie de contacto. Comparar puntos de ebullición requiere mantener razonablemente constantes otras variables; no basta con contar enlaces polares.','Etanol y dimetil éter comparten fórmula molecular, pero el alcohol puede donar puentes de hidrógeno. Usa esta diferencia para justificar cualitativamente sus distintas temperaturas de ebullición.'],
 ['Los coeficientes de una ecuación ajustada relacionan cantidades de sustancia, no masas directamente. Convierte cada reactivo a moles y compara n/coeficiente para identificar el limitante. El rendimiento teórico supone transformación completa según esa ecuación; el rendimiento experimental puede disminuir por reacciones secundarias, pérdidas o conversión incompleta.','Para 2 H₂ + O₂ → 2 H₂O, 3 mol de H₂ y 2 mol de O₂ producen como máximo 3 mol de agua: H₂ limita y sobra 0,5 mol de O₂.'],
 ['PV=nRT aproxima gases diluidos alejados de condensación. La concentración de una disolución relaciona cantidad de soluto con una base definida: volumen de disolución, masa de disolvente o cantidad total. Temperatura afecta magnitudes volumétricas; molaridad y molalidad no son intercambiables. Antes de calcular, distingue fase, composición y condiciones.','Disolver 0,10 mol y aforar a 0,50 L da 0,20 mol/L. Añadir 0,50 L de agua no garantiza un volumen final exactamente aditivo en toda mezcla real.'],
 ['El análisis dimensional trata las unidades como factores algebraicos. Una igualdad física debe conservar dimensiones y las conversiones deben cancelar las unidades originales. Diferencia magnitudes extensivas, como masa, e intensivas, como densidad. Las temperaturas absolutas se convierten a kelvin antes de emplearlas en leyes de gases o factores termodinámicos.','1,25 g/mL × 1000 mL/L = 1250 g/L. Comprueba por cancelación y explica por qué convertir °C a K exige una suma y no un factor.'],
 ['La incertidumbre expresa la dispersión atribuible al resultado bajo información y modelo especificados. Las cifras significativas ayudan a comunicar resolución, pero no reemplazan un presupuesto de incertidumbre. Redondea al final, conserva dígitos de guarda y distingue resolución instrumental, repetibilidad y posibles sesgos de calibración.','Tres lecturas cercanas pueden ser precisas y estar desplazadas por una balanza descalibrada. Presenta promedio, unidad e incertidumbre; explica qué información no aportan las cifras decimales por sí solas.'],
 ['La seguridad comienza con identificar peligros, vías de exposición y controles antes del trabajo. Las fichas de datos de seguridad, procedimientos institucionales y segregación de residuos orientan decisiones concretas. El cuaderno registra condiciones, observaciones y desviaciones de forma trazable; no se reconstruye únicamente desde resultados finales.','Antes de una práctica documental de disoluciones, identifica incompatibilidades y el contenedor de residuos previsto. No mezcles residuos desconocidos ni sustituyas un procedimiento institucional por una instrucción informal.'],
 ['Una fórmula expresa composición y, según su tipo, información estructural. Para sales simples, la suma de cargas debe ser cero; los números de oxidación son una contabilidad formal, distinta de cargas parciales. La nomenclatura debe permitir reconstruir inequívocamente la especie y distinguir hidratación, coordinación y proporciones estequiométricas.','FeCl₂ contiene formalmente Fe(II), mientras FeCl₃ contiene Fe(III). Justifica cada estado con la neutralidad y explica por qué los subíndices no se cambian al ajustar una reacción.'],
 ['El mol conecta número de entidades y cantidad de sustancia mediante la constante de Avogadro. La masa molar transforma gramos en moles; composición porcentual compara la contribución másica de cada elemento con la masa molar total. Especifica qué entidad cuentas: átomos, moléculas, iones o unidades fórmula.','En agua, la contribución aproximada del hidrógeno es 2/18 × 100 ≈ 11,1 %. No debe confundirse con la fracción de átomos de hidrógeno, que es 2/3.'],
 ['La fórmula empírica muestra la relación entera mínima entre elementos; la molecular añade el número real de átomos de una molécula. Convierte masas a moles, divide por la menor cantidad y busca una proporción compatible con incertidumbre. La masa molar experimental permite hallar el múltiplo entero.','Una relación C:H:O = 1:2:1 corresponde a CH₂O. Si la masa molar es aproximadamente 180 g/mol, el factor es seis y la fórmula molecular es C₆H₁₂O₆.'],
 ['Balancear conserva elementos y, en ecuaciones iónicas, carga. Se modifican coeficientes, nunca identidades químicas. Rendimiento y conversión son diferentes: convertir reactivo no implica obtener solo el producto deseado. Para evaluar eficiencia, informa qué producto se mide y cómo se determinó su pureza.','Si el máximo teórico es 10,0 g de producto puro y se obtienen 8,0 g puros, el rendimiento es 80 %. Una muestra húmeda de 10,5 g no demuestra un rendimiento superior al 100 %.'],
 ['En medio acuoso, la ecuación molecular puede ocultar iones espectadores. La forma iónica neta conserva las especies que cambian y representa precipitación, neutralización o transferencia electrónica. Solo disocia especies que realmente se tratan como electrolitos fuertes en esas condiciones; sólidos, gases y ácidos débiles requieren otro tratamiento.','Ag⁺(aq) + Cl⁻(aq) → AgCl(s) elimina Na⁺ y NO₃⁻ de la ecuación completa. Identifica qué medición permitiría comprobar que se formó una fase sólida.'],
 ['Preparar una disolución exige definir concentración objetivo, pureza del reactivo y volumen final. En una dilución se conserva el soluto si no hay reacción ni pérdidas: c₁V₁=c₂V₂. Aforar significa completar hasta una marca bajo condiciones apropiadas, no sumar volúmenes nominales sin comprobarlos.','Para 100 mL de 0,10 mol/L desde 1,0 mol/L, calcula 10 mL de disolución madre y completa hasta 100 mL siguiendo el procedimiento y material volumétrico del laboratorio.'],
 ['La densidad ρ=m/V permite relacionar masa y volumen a temperatura especificada. Una correlación densidad-concentración necesita calibración de la misma matriz; sales diferentes pueden producir densidades parecidas. Controla temperatura, burbujas, evaporación y limpieza; una propiedad física aislada rara vez identifica toda una composición.','Una muestra de 25,0 mL con masa 27,5 g tiene densidad 1,10 g/mL. Explica qué datos adicionales necesitarías para convertirla en concentración de sacarosa.'],
 ['Analizar datos implica conservar originales, visualizar tendencias y evaluar un modelo con residuos. Las repeticiones deben corresponder a la variabilidad que interesa estimar. No descartes observaciones solo porque dificultan una tendencia; documenta criterios previos, causas técnicas comprobables y análisis de sensibilidad.','Ajusta masa frente a volumen para estimar densidad como pendiente. Un intercepto distinto de cero puede sugerir tara incorrecta; examínalo antes de forzar el ajuste por el origen.'],
 ['Un informe separa procedimiento, datos, tratamiento e interpretación. Un resultado debe incluir unidad, condiciones, incertidumbre y alcance. Distingue lo medido de lo calculado y conserva suficientes detalles para reconstruir el análisis. Las conclusiones deben responder a la pregunta inicial sin exceder la resolución del experimento.','Al comparar dos densidades, evalúa su diferencia frente a las incertidumbres. Redacta una conclusión que indique compatibilidad experimental en lugar de afirmar identidad química de las muestras.']
 ]},
 'general-ii': {context:'El equilibrio y la espontaneidad describen tendencias y estados finales, mientras la cinética describe la rapidez de aproximación. Una constante solo tiene sentido junto con la reacción, la temperatura y la convención de actividad. Para una disolución real, el balance de materia sigue siendo obligatorio aunque cambie el modelo de idealidad. Conviene resolver primero la estructura del problema y después justificar las aproximaciones numéricas empleadas.',reading:general,lessons:[
 ['La entalpía H=U+pV permite relacionar intercambio térmico y reacción a presión constante cuando solo interviene trabajo de expansión. La calorimetría infiere calor desde cambios de temperatura y capacidades caloríficas. Debe incluirse el recipiente y distinguir calor absorbido por el entorno del signo asignado al sistema.','Si el agua absorbe 418 J y el calorímetro es despreciable, la reacción cede aproximadamente 418 J. Explica cómo cambiaría el cálculo con un calorímetro de capacidad no despreciable.'],
 ['La entropía cuantifica la distribución de energía y la multiplicidad compatible con un estado. A temperatura y presión constantes, ΔG=ΔH−TΔS orienta la espontaneidad. ΔG de reacción depende de la composición; ΔG° y ΔG no son equivalentes. Una transformación favorable puede ser extremadamente lenta.','Para ΔH=20 kJ/mol y ΔS=100 J/(mol·K), el cambio de signo idealizado ocurre a 200 K si ambos valores se consideran constantes. Examina la limitación de esa aproximación.'],
 ['El equilibrio ácido-base combina transferencias de protones, balances y constantes. pH se define mediante actividad de H⁺; usar concentración es una aproximación para ciertos medios diluidos. La fortaleza de un ácido no equivale a su concentración. Las especies polipróticas requieren considerar disociaciones sucesivas y condiciones dominantes.','Un ácido débil de concentración C puede aproximarse con [H⁺]≈√(KaC) solo si la disociación es pequeña y otras contribuciones son despreciables. Comprueba x/C después de calcular.'],
 ['La solubilidad depende de equilibrios de disolución y reacciones que consumen especies libres, como complejación o protonación. El producto de solubilidad usa actividades iónicas, no la concentración total del metal si existen complejos. Un ligando puede aumentar la cantidad disuelta mientras reduce el metal libre.','Para AgCl idealizado, Ksp=[Ag⁺][Cl⁻]. Explica por qué agregar un ligando que compleja Ag⁺ puede favorecer la disolución, sin que cambie Ksp a temperatura fija.'],
 ['La ley de velocidad expresa dependencia experimental con concentraciones bajo condiciones definidas. Sus órdenes no se deducen automáticamente de la ecuación global. La constante cambia con temperatura y sus unidades dependen del orden total. El mecanismo propuesto debe reproducir tanto la ley como otras evidencias.','Si v=k[A]²[B], duplicar A cuadruplica v y duplicar B la duplica. Distingue estos exponentes experimentales de los coeficientes de una reacción global.'],
 ['Una celda separa semirreacciones y permite relacionar energía libre y potencial: ΔG=−nFE. El ánodo es siempre el lugar de oxidación y el cátodo de reducción; sus signos eléctricos dependen del modo galvánico o electrolítico. Los potenciales tabulados corresponden a estados estándar y una convención de referencia.','Un E de celda positivo implica ΔG negativo para la reacción escrita. Si inviertes la reacción, cambian ambos signos, pero no el número positivo de electrones transferidos.'],
 ['Las propiedades coligativas reflejan la disminución del potencial químico del disolvente al añadir soluto. En modelos diluidos aparecen relaciones para presión osmótica, congelación y ebullición. Electrolitos, asociación y no idealidad modifican el número efectivo de partículas; el factor de van ’t Hoff no es siempre un entero constante.','Una disolución ideal de glucosa tiene aproximadamente una partícula de soluto por molécula. Compara con NaCl diluido y explica por qué la aproximación de dos partículas puede fallar al concentrar.'],
 ['Los diagramas de fase muestran regiones de estabilidad y fronteras de coexistencia según variables especificadas. En una línea pueden coexistir fases; los puntos triple y crítico tienen significados distintos. La regla de fases restringe grados de libertad, pero no informa por sí sola de la rapidez de nucleación.','En un diagrama p-T de una sustancia pura, seguir una isóbara puede atravesar sólido, líquido y vapor. Describe por qué la ruta depende de la presión seleccionada.'],
 ['La actividad representa la concentración termodinámicamente efectiva respecto a un estado estándar. Un coeficiente de actividad recoge desviaciones del modelo ideal y depende de composición y condiciones. Mantener constantes de equilibrio termodinámicas requiere actividades; constantes basadas en concentraciones pueden variar con la fuerza iónica.','Dos disoluciones con igual concentración de un ion pueden tener actividades distintas si sus fuerzas iónicas difieren. Explica por qué una calibración debe atender también a la matriz.'],
 ['Disolver combina separación de partículas y nuevas interacciones soluto-disolvente. La solvatación puede favorecer entalpía, mientras mezcla y organización del disolvente afectan entropía. La regla “semejante disuelve semejante” es orientativa: ionización, temperatura y composición pueden cambiar radicalmente la solubilidad.','Un ácido orgánico puede aumentar su solubilidad aparente al ionizarse. Distingue ese equilibrio químico de una simple mejora de interacciones de la especie neutra con el agua.'],
 ['Los balances de masa contabilizan todas las formas químicas de un componente y el balance de carga impone electroneutralidad macroscópica. Se combinan con constantes para obtener concentraciones. No omitas complejos o especies minoritarias sin comprobar su efecto en el resultado o en la precisión requerida.','Para un ácido monoprótico, C=[HA]+[A⁻]. En una disolución sin otros iones, [H⁺]=[A⁻]+[OH⁻]; ambas relaciones deben cumplirse simultáneamente.'],
 ['Un tampón contiene un par conjugado capaz de amortiguar pequeñas adiciones de ácido o base. Henderson-Hasselbalch deriva del equilibrio y requiere una interpretación adecuada de actividades y concentraciones. La capacidad depende de cantidades totales; mismo pH no significa misma resistencia a una perturbación.','Con cantidades iguales de ácido y base conjugada, pH≈pKa en condiciones apropiadas. Compara un tampón 0,01 M con uno 0,10 M ante la misma adición de ácido.'],
 ['Una curva de titulación relaciona respuesta y volumen añadido. Antes, cerca y después de equivalencia dominan balances diferentes; el punto final observado no coincide necesariamente con equivalencia estequiométrica. Seleccionar indicador o detección instrumental exige atender al salto de señal y a interferencias.','En ácido débil-base fuerte, la equivalencia suele ser básica por hidrólisis de la base conjugada. Explica por qué pH 7 no identifica universalmente la equivalencia.'],
 ['Los equilibrios acoplados comparten especies y se desplazan conjuntamente. Resolverlos por etapas puede ser útil si una reacción domina, pero cada simplificación debe verificarse con las concentraciones finales. Métodos numéricos requieren balances bien planteados y soluciones físicamente admisibles, no solo convergencia matemática.','En precipitación con ligandos, combina Ksp, formación del complejo y balance total del metal. Una concentración libre pequeña no demuestra que quede poco metal total en solución.'],
 ['Para estimar una constante se mide una propiedad relacionada con composición en equilibrio y se ajusta un modelo de especies. Deben distinguirse equilibrio real y estado estacionario, controlarse temperatura y evaluarse actividad. Las señales indirectas necesitan una relación calibrada con la especie que interesa.','Una absorbancia puede estimar un complejo mediante Beer-Lambert si se conocen contribuciones de otras especies. Comprueba que esperar más tiempo no cambia la señal antes de llamarla equilibrio.'],
 ['Ajustar datos cinéticos requiere una relación entre señal y concentración, condiciones iniciales y un modelo temporal. Linealizar puede alterar la estructura del error; el ajuste no lineal permite conservarla cuando está bien especificada. Inspecciona residuos, intervalos de parámetros y puntos influyentes.','Para primer orden, A(t)=A₀e^(−kt). Compara ajustar esta función con ajustar ln A: errores pequeños y constantes en A no se vuelven constantes al tomar logaritmos.'],
 ['La ecuación de Nernst vincula potencial y cociente de reacción: E=E°−RT ln Q/(nF). Q se construye con actividades y exponentes estequiométricos, excluyendo fases puras según el estado estándar. El valor 0,05916 V para logaritmos decimales corresponde aproximadamente a 298 K y se divide por n.','Si Q aumenta diez veces a 298 K para n=1, E disminuye aproximadamente 59 mV. Explica por qué esa pendiente cambia con temperatura o número de electrones.'],
 ['Una indagación establece pregunta, modelo, variables, controles y criterio de interpretación antes de recoger datos. La discusión debe distinguir incertidumbre aleatoria y posibles sesgos, y considerar explicaciones alternativas. Comunicar un resultado incluye suficientes datos y condiciones para repetir o revisar el razonamiento.','Diseña una comparación de velocidades a dos temperaturas manteniendo composición y medición constantes. Indica cómo evitar confundir tiempo de calentamiento con tiempo efectivo de reacción.']
 ]},
 'inorganica-avanzada': {context:'La química inorgánica interpreta propiedades mediante estructura electrónica, simetría, enlaces y composición. Los modelos iónico, covalente y de campo de ligandos son aproximaciones complementarias, no etiquetas absolutas. Es necesario separar estabilidad termodinámica de inercia cinética y contrastar una estructura propuesta con más de una técnica. La predicción de color, magnetismo o reactividad depende del estado de oxidación, geometría y entorno del centro químico.',reading:[...general,['IUPAC · Guía breve de nomenclatura inorgánica (español)','https://iupac.org/wp-content/uploads/2016/07/20151106GuiaBreveNQIEspayol.pdf']],lessons:[
 ['La geometría de coordinación describe posiciones de átomos donadores; denticidad cuenta cuántos pertenecen a un ligando. La simetría permite clasificar operaciones que dejan indistinguible la estructura y predecir equivalencia de posiciones. Número de coordinación igual no obliga a geometría igual: cuatro donadores pueden organizarse tetraédricamente o en un plano.','Compara un complejo tetraédrico ML₄ y uno cuadrado plano. Identifica qué operaciones de simetría y propiedades magnéticas ayudarían a diferenciarlos.'],
 ['El campo cristalino modela interacciones electrostáticas y el campo de ligandos incorpora covalencia mediante orbitales. El desdoblamiento d depende de geometría y ligandos; su competencia con apareamiento determina configuraciones de espín en ciertos casos. Color y magnetismo aportan evidencia, pero requieren considerar reglas de selección y acoplamiento.','Un centro octaédrico d⁶ puede tener alto o bajo espín. Dibuja ambas ocupaciones y cuenta electrones desapareados sin asumir que todo ligando conduce al mismo desdoblamiento.'],
 ['La sustitución cambia ligandos y puede avanzar por rutas asociativas, disociativas o de intercambio. La ley de velocidad, volumen de activación y estereoquímica permiten distinguir modelos. Inercia significa lentitud de sustitución bajo condiciones dadas; no equivale a una constante de formación elevada.','Un complejo muy estable puede intercambiar ligandos rápidamente. Propón una medición temporal que determine labilidad y otra de equilibrio que determine estabilidad.'],
 ['La transferencia electrónica puede ocurrir por esfera externa o con un puente de esfera interna. Reorganizar disolvente y enlaces contribuye a la barrera de activación. Potencial redox favorable no basta para predecir velocidad: también importan acoplamiento electrónico, distancia y reorganización.','Compara transferencia entre complejos sin ligando puente y otra mediada por un haluro compartido. Explica qué cambio estructural podría dar evidencia de una ruta interna.'],
 ['Los ciclos organometálicos combinan coordinación, inserción, eliminación y pasos redox según el sistema. La especie más abundante no siempre es la catalíticamente activa. Un mecanismo defendible conserva átomos, carga y metal y relaciona etapas con selectividad, velocidad y desactivación.','En un ciclo conceptual, cuenta ligandos y electrones antes y después de adición oxidante. Comprueba que una etapa final regenera la especie inicial en lugar de consumirla.'],
 ['Los metales biológicos participan en transporte, activación de sustratos y transferencia electrónica. Su función depende de coordinación, estado redox y entorno proteico. Disponibilidad de metal total no equivale a concentración libre; proteínas y transportadores controlan especiación y evitan reacciones no deseadas.','Contrasta la función del hierro en transporte de oxígeno y transferencia electrónica. Explica por qué conocer solamente el elemento no permite asignar una función bioquímica.'],
 ['Configuraciones electrónicas, carga efectiva y energías orbitales organizan tendencias de los elementos. Para cationes de transición se retiran primero los electrones externos correspondientes, sin interpretar el orden de llenado como un orden energético invariable. Estados de oxidación accesibles cambian con ligandos y medio.','Fe neutro se representa aproximadamente [Ar]3d⁶4s²; Fe²⁺ es d⁶. Relaciona el conteo con posibles propiedades, indicando qué información geométrica todavía falta.'],
 ['Las operaciones de simetría incluyen rotaciones, reflexiones, inversión y rotaciones impropias. Un grupo puntual reúne operaciones compatibles con una molécula idealizada. Debe elegirse primero una geometría; vibraciones, sustituciones o distorsiones pueden reducir la simetría observada respecto del modelo más sencillo.','Una molécula angular como H₂O posee eje C₂ y planos de simetría en su geometría de equilibrio. Verifica cada operación siguiendo posiciones atómicas, no solo el dibujo.'],
 ['Las representaciones describen cómo cambia una base de coordenadas u orbitales bajo simetría. Sus caracteres permiten descomponer una representación reducible en irreducibles y reconocer combinaciones compatibles. Las tablas no sustituyen definir la base; una asignación vibracional necesita contar modos y considerar actividades IR y Raman.','Para una molécula no lineal con N átomos hay 3N−6 modos vibracionales. Explica por qué restar traslaciones y rotaciones precede a interpretar una tabla de caracteres.'],
 ['Los orbitales moleculares se forman combinando funciones de simetría y energía compatibles. Ocupación de niveles enlazantes y antienlazantes determina orden de enlace aproximado y contribuye al magnetismo. Diagramas de especies distintas no se copian sin revisar mezcla orbital y orden relativo de energías.','O₂ presenta electrones desapareados en orbitales antienlazantes. Explica por qué una estructura de Lewis sola no representa satisfactoriamente esta propiedad magnética.'],
 ['En el bloque principal, tamaño, electronegatividad, energía de enlace y estabilización de estados de oxidación orientan reactividad. La coordinación y el medio pueden estabilizar especies que una regla simple no predice. Compara elementos de un grupo distinguiendo tendencias generales y excepciones ligadas a estructura electrónica.','Compara estabilidad relativa de estados bajos y altos de oxidación en elementos pesados del bloque p. Justifica por qué extrapolar directamente desde el elemento más ligero puede fallar.'],
 ['Una estructura cristalina combina red y base; defectos puntuales o extendidos modifican propiedades del sólido. Vacancias, intersticiales y sustituciones deben respetar la compensación de carga cuando corresponde. Difracción identifica estructura promedio, pero puede requerir técnicas locales para estudiar defectos y desorden.','Una vacancia catiónica en un óxido puede compensarse con otros defectos o cambios redox. Plantea un balance de carga antes de atribuirle conductividad.'],
 ['La energía reticular refleja estabilización al formar un cristal desde especies de referencia gaseosas. Ciclos termoquímicos permiten relacionarla con magnitudes medibles y estimaciones. Tamaño y carga iónica orientan tendencias, pero polarización y covalencia limitan modelos puramente electrostáticos.','Compara cualitativamente dos sales de igual estructura con cargas diferentes. Explica por qué un ciclo de Born-Haber necesita convenciones de signo coherentes.'],
 ['Los materiales funcionales se seleccionan por respuesta óptica, eléctrica, magnética o catalítica bajo condiciones de uso. Composición, microestructura y defectos actúan conjuntamente. Caracterización debe vincular estructura y propiedad con controles; observar una fase cristalina no demuestra por sí solo desempeño tecnológico.','Para evaluar un semiconductor, combina información de fase, morfología y respuesta eléctrica. Distingue conductividad del material de resistencia de contacto en el dispositivo.'],
 ['Los espectros electrónicos revelan transiciones d-d o transferencia de carga, con intensidades y energías dependientes de simetría. La susceptibilidad magnética ayuda a inferir espín, pero puede incluir acoplamientos y contribuciones orbitales. Una asignación consistente combina ambos tipos de evidencia.','Una banda intensa puede ser de transferencia de carga y no una transición d-d. Contrasta su intensidad con la predicción de selección antes de estimar desdoblamiento.'],
 ['El conteo electrónico formal evalúa electrones aportados por metal y ligandos usando un método coherente. La regla de 18 electrones resulta útil para numerosos complejos, pero no es una ley universal: existen especies estables de 16 electrones y complejos con otras ocupaciones.','Cuenta electrones de un complejo con ligandos CO mediante un solo convenio. Explica cómo mezclar conteo iónico y neutro puede producir una respuesta incorrecta.'],
 ['Una propuesta sintética debe definir composición objetivo y evidencias para distinguir producto, impurezas e isómeros. Rendimiento, pureza y estructura son preguntas distintas. La caracterización puede combinar análisis elemental, espectroscopía, magnetismo y difracción según el problema; una señal aislada rara vez basta.','Un sólido del color esperado no confirma identidad. Diseña un conjunto documental de al menos dos técnicas que discrimine ligando libre, sal inicial y complejo final.'],
 ['Criticar un mecanismo catalítico exige buscar predicciones comprobables y alternativas. Orden cinético, marcaje, intermedios observados y dependencia de selectividad restringen modelos, pero ninguna evidencia aislada suele probar todos los pasos. Incluye balances y posibles especies fuera del ciclo productivo.','Si la velocidad se satura al aumentar sustrato, discute un preequilibrio de unión y una alternativa por inhibición. Señala qué experimento conceptual permitiría diferenciarlas.']
 ]},
};

export function lessonId(slug: string, index: number) {
  const base = 'pregrado-' + slug;
  return index < 6 ? `${base}-u${Math.floor(index / 2) + 1}-t${index % 2 + 1}` : `${base}-extension-${Math.floor((index - 6) / 4) + 1}-t${(index - 6) % 4 + 1}`;
}
const lessons = new Map(Object.entries(courseNotes).flatMap(([slug, course]) => course.lessons.map(([summary, example], n) => {
  const readings = [...course.reading];
  if (slug === 'volatilomica' && n === 22) readings.push(['IONICON · Principio PTR-MS (inglés)', 'https://www.ionicon.com/knowledge-base/detail/ptr-ms']);
  if (slug === 'volatilomica' && n === 23) readings.push(['Syft · Principio SIFT-MS (inglés)', 'https://syft.com/sift-ms-technology/']);
  return [lessonId(slug, n), {body: 'Resumen del tema\n\n' + summary + '\n\nConexión con la asignatura\n\n' + course.context,
    examples: 'Aplicación razonada\n\n' + example,
    activities: '1. Resuelve o desarrolla la aplicación anterior indicando los supuestos utilizados.\n2. Explica qué dato, observación o cálculo adicional permitiría comprobar tu respuesta.\n3. Compara tu razonamiento con una lectura del tema y señala una limitación del modelo.\n\nEntrega: razonamiento, unidades cuando correspondan y conclusión sustentada.',
    bibliography: 'Lecturas para profundizar (consulta el capítulo correspondiente al tema). Resumen didáctico original en español; no es una transcripción de estas obras.\n\n' + readings.map(([title, url]) => title + '\n' + url).join('\n\n')} ] as const;
})));

export function enrichUniversityLessons(items: Item[]): Item[] {
  return items.map(item => {
    const lesson = lessons.get(item.id);
    // An editor save is authoritative, including intentionally empty fields.
    if (!lesson || item.kind !== 'topic' || item.updatedAt) return item;
    return {...item, ...lesson, description: 'Resumen, aplicación y actividad de ' + item.title.toLowerCase() + '.', example: false};
  });
}
